-- Official house-owned seed snippets. Idempotent.
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-usestate', 'react', '19.0.0', 'useState declares a state variable', 'useState is a React Hook that lets you add a state variable to a component. Call const [state, setState] = useState(initialValue) at the top level of your component. React keeps the state between re-renders. The setter replaces the previous value; passing an updater function receives the pending state. This is a short excerpt for agents, not a substitute for the full API reference.', 'https://react.dev/reference/react/useState', 'CC-BY-4.0', '17bdb418d4816f02291d8ddcb347f564926288f9c24c369bd7f2bf3e225189ed', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-rules-of-hooks', 'react', '19.0.0', 'Rules of Hooks', 'Only call Hooks at the top level of a React function component or a custom Hook. Do not call Hooks inside loops, conditions, nested functions, or after an early return. Only call Hooks from React functions, not from regular JavaScript functions or class components. These rules let React preserve Hook state across renders in a stable order.', 'https://react.dev/reference/rules/rules-of-hooks', 'CC-BY-4.0', '0c2c1064eb18dbc2ffcef9b5940643fdaa4205a326960b036fbce0a30670c3fc', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-useeffect', 'react', '19.0.0', 'useEffect synchronizes with an external system', 'useEffect lets you synchronize a component with an external system. React runs the effect after the component commits to the screen. Return a cleanup function to undo the subscription or timer. Declare every reactive value used inside the effect in the dependency array. Effects are for external systems; you usually do not need an Effect to transform data for rendering.', 'https://react.dev/reference/react/useEffect', 'CC-BY-4.0', '9134b15b9635c3234e125fb23bf05431b85248ac6558c07b4ebaeda59cece978', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-use-client', 'react', '19.0.0', 'use client marks a Client Component module', 'The ''use client'' directive tells bundlers to treat the module and its imports as Client Components. Put it at the top of the file, before imports. Use it when the module uses state, effects, or browser-only APIs. Server Components are the default in React Server Components apps and do not need a directive. Client Components can import other Client Components, not Server Components.', 'https://react.dev/reference/rsc/use-client', 'CC-BY-4.0', 'cff8fccda8c832ee5939911835114ebb544266bbac297fd156a5c62bdd436135', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('express-basic-routing', 'express', '5.x', 'Basic routing with app.METHOD', 'Routing determines how an Express app responds to a client request for a particular path and HTTP method. app.get(''/path'', handler) handles GET requests. The handler receives (req, res, next). Send a response with res.send, res.json, or res.end. Path patterns can include named parameters such as /users/:userId, available as req.params.userId.', 'https://expressjs.com/en/starter/basic-routing.html', 'MIT', '2e848c7611e3cc5020a118e2182df7916858a9bbeccb8ec61f8944a6241eb748', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('express-middleware', 'express', '5.x', 'Using middleware', 'Middleware functions have access to the request, the response, and the next function in the cycle. They can execute code, change req and res, end the cycle, or call next() to continue. Application-level middleware is bound with app.use or app.METHOD. If a middleware function does not call next() or end the response, the request hangs. Error-handling middleware takes four arguments: (err, req, res, next).', 'https://expressjs.com/en/guide/using-middleware.html', 'MIT', '6554e7931d90b1cf81e748d4e588c91bdaa2c70c4f842b1557eeb7ba818eb93f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('express-error-handling', 'express', '5.x', 'Error handling', 'Define error-handling middleware last, after other app.use and route calls, with four arguments: (err, req, res, next). In Express 5, rejected promises in middleware and handlers are passed to the error handler automatically. You can still call next(err) to skip to the error handler. Do not write to the response after headers have been sent.', 'https://expressjs.com/en/guide/error-handling.html', 'MIT', '45ee7287377bb3a47a697933a82d1af1ef842fb8d5b4b5bae6e05dd90124814e', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('zod-safeparse', 'zod', '4.x', 'safeParse vs parse', 'schema.parse(data) validates and returns the typed value, or throws a ZodError if validation fails. schema.safeParse(data) returns a discriminated result: { success: true, data } or { success: false, error }. Prefer safeParse in request handlers and agent tools so a bad payload does not throw. The error object lists issues with a path and message for each failed check.', 'https://zod.dev/api', 'MIT', '10a040aacfe9f634cf2fd052c6ea1f48db96f29dc057535c93887b5852e2d255', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('zod-object', 'zod', '4.x', 'z.object defines a typed object schema', 'z.object({ name: z.string(), count: z.number().int() }) describes an object and infers its TypeScript type. Unknown keys are stripped by default in many setups; use .strict() to reject them or .passthrough() to keep them. Build nested objects by composing schemas. Optional fields use .optional() or .default(value).', 'https://zod.dev/api', 'MIT', 'f4bf8648d5a643598e4eacb947a36f9b59150396ff15d8ba9ee8a2d5d5a2a553', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('zod-infer', 'zod', '4.x', 'z.infer gets the TypeScript type from a schema', 'Use z.infer<typeof schema> to extract the output TypeScript type of a Zod schema. Use z.input<typeof schema> when the input type differs from the output, for example after .transform or .default. Inferring types from the schema keeps runtime validation and compile-time types in sync so you do not maintain a parallel interface.', 'https://zod.dev/api', 'MIT', 'fc72b113b34b4bdc6c91707260535b39c1778564daafc35663bb07c895d0e888', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('next-app-router', 'nextjs', '15.0.0', 'App Router uses the app directory', 'The Next.js App Router is defined by files in the app/ directory. page.tsx is a route''s UI, layout.tsx wraps segments and preserves state on navigation, loading.tsx and error.tsx define fallback UI, and route.ts defines a Route Handler. Folders name the URL segment. This is a short excerpt for agents, not a substitute for the full App Router reference.', 'https://nextjs.org/docs/app/building-your-application/routing', 'MIT', 'eb6a6369dfc71eb8c58e92c93e7356f7db1b0aa8f2c0e1fb1ca67df00a55b9dd', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('next-server-actions', 'nextjs', '15.0.0', 'Server Actions run on the server from a form or call', 'A Server Action is an async function marked with the ''use server'' directive. You can pass it to a form action or call it from a Client Component. Next.js creates a POST endpoint for the action and treats the returned data as a mutation so the router can refresh cached data. Validate arguments on the server; do not trust client input. This is a short excerpt for agents, not a substitute for the full reference.', 'https://nextjs.org/docs/app/building-your-application/data-fetching/server-actions-and-mutations', 'MIT', '5953ea54c2dd3417ff2e28c579e958108c4b5d686aac9d717349c06c8d27a08a', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('next-generate-metadata', 'nextjs', '15.0.0', 'generateMetadata sets per-route title and Open Graph tags', 'Export generateMetadata from a page or layout to set a route''s <title>, description, and Open Graph fields. The function can be async and receives the route params and searchParams. Returned fields are shallow-merged with parent layouts. Use the metadata object instead when the values are static. This is a short excerpt for agents, not a substitute for the full Metadata API.', 'https://nextjs.org/docs/app/api-reference/functions/generate-metadata', 'MIT', '97c1bff1a9b0f5daab5b133855176db4b0dde7efcd4cd91bec799ef794a9396f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('node-fs-promises', 'nodejs', '22.x', 'fs/promises is the async file API', 'import { readFile, writeFile, mkdir } from ''node:fs/promises'' returns Promises instead of using callbacks. readFile(path, ''utf8'') resolves to a string. writeFile overwrites by default; use the flag option to append. Paths may be strings or URL file: objects. Prefer this module over fs.promises in new ESM code. This is a short excerpt for agents, not a substitute for the full Node.js API.', 'https://nodejs.org/docs/latest-v22.x/api/fs.html#promises-api', 'MIT', '72a97766a5fde4520352537074ee6776dee90867875142e5301b9ecc6623c69f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('node-fetch', 'nodejs', '22.x', 'fetch is a global HTTP client in Node.js', 'Node.js provides a global fetch() that follows the WHATWG Fetch Standard, plus Request, Response, Headers, and FormData. await fetch(url) returns a Response; call response.json() or response.text() to read the body. For a POST, pass { method: ''POST'', headers, body }. Undici implements this API. This is a short excerpt for agents, not a substitute for the full Node.js API.', 'https://nodejs.org/docs/latest-v22.x/api/globals.html#fetch', 'MIT', 'cd6a5efbae120ff76abbfaf872f8b05b54d527d573ff43c849a3adca5d1af0e9', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('node-path', 'nodejs', '22.x', 'path.join and path.extname build portable file paths', 'import path from ''node:path''. path.join(''src'', ''index.ts'') joins segments with the platform separator and normalizes ''.'' and ''..''. path.extname(''a.ts'') returns ''.ts''. path.resolve starts from the current directory unless given an absolute segment. On Windows, path.win32 and path.posix expose explicit variants. This is a short excerpt for agents, not a substitute for the full Node.js API.', 'https://nodejs.org/docs/latest-v22.x/api/path.html', 'MIT', 'b87b19078098059869cca0ac58dd838a02ffb653c5f642b61da4dadce174d4c7', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ts-strict', 'typescript', '5.x', 'strict turns on the recommended type-checking suite', 'Setting "strict": true in tsconfig.json enables strictNullChecks, noImplicitAny, strictFunctionTypes, strictBindCallApply, strictPropertyInitialization, and useUnknownInCatchVariables. Under strictNullChecks, string | null is not assignable to string without a narrowing check. Prefer enabling strict in new projects rather than toggling flags one by one. This is a short excerpt for agents, not a substitute for the TypeScript Handbook.', 'https://www.typescriptlang.org/tsconfig/#strict', 'CC-BY-4.0', '100414cc2622845c7ce760e11e24728eed895297aa9414b3a1dbd0663c97307d', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ts-utility-types', 'typescript', '5.x', 'Partial, Pick, Omit, and Record are built-in utility types', 'TypeScript ships utility types that transform other types. Partial<T> makes every property optional. Required<T> makes them required. Pick<T, K> keeps a key set, Omit<T, K> drops a key set, and Record<K, T> builds an object type from keys K to values T. ReturnType<F> and Parameters<F> extract a function''s return and parameter types. This is a short excerpt for agents, not a substitute for the TypeScript Handbook.', 'https://www.typescriptlang.org/docs/handbook/utility-types.html', 'CC-BY-4.0', 'c7603c858f743fcb49ef3d1b2d05f33c1bb06005420c2d0b8ebebd21cba6d68a', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ts-satisfies', 'typescript', '5.x', 'satisfies checks a value against a type without widening it', 'The satisfies operator validates that an expression matches a type while keeping the expression''s more specific inferred type. For example, const palette = { red: [255, 0, 0], green: ''#00ff00'' } satisfies Record<string, string | number[]> still lets you use palette.red.map because red stays a number array. Use it when as would hide mistakes or when an annotation would widen literals. This is a short excerpt for agents, not a substitute for the TypeScript Handbook.', 'https://www.typescriptlang.org/docs/handbook/release-notes/typescript-4-9.html#the-satisfies-operator', 'CC-BY-4.0', '4f6949d4c27b7f79648eae1c4797927ddfe53c19c31f52a6cc7658499469c008', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('py-pathlib', 'python', '3.13', 'pathlib.Path is the object-oriented path API', 'from pathlib import Path. Path(''src'') / ''app.py'' joins paths in a portable way. Path.read_text() and Path.write_text() handle encoding, Path.iterdir() lists a directory, Path.glob(''**/*.py'') searches recursively, and Path.exists() / Path.is_file() test the filesystem. Prefer Path over os.path in new code. This is a short excerpt for agents, not a substitute for the Python standard library docs.', 'https://docs.python.org/3/library/pathlib.html', 'PSF-2.0', '94ad0d8f565ffb382baf643eb1e62c5e0247b01b9ba129c3cc4af30aaf38a19b', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('py-dataclasses', 'python', '3.13', 'dataclasses generate __init__ and comparison methods', 'from dataclasses import dataclass, field. @dataclass on a class synthesizes __init__, __repr__, and comparison methods from annotated fields. Use field(default_factory=list) for mutable defaults. @dataclass(frozen=True, slots=True) makes instances immutable and uses __slots__. keyword-only fields can be marked with kw_only=True. This is a short excerpt for agents, not a substitute for the Python standard library docs.', 'https://docs.python.org/3/library/dataclasses.html', 'PSF-2.0', '94025574b05b0d2582a9c4d8fb16c6e0486b7fbba48816fcdee8154b28265c15', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('py-asyncio', 'python', '3.13', 'asyncio.run and TaskGroup drive async programs', 'asyncio.run(main()) starts an event loop, runs the coroutine, and shuts the loop down. Inside async functions, await asyncio.sleep(n) yields, and asyncio.gather(*coros) waits for many tasks. In 3.11+, async with asyncio.TaskGroup() as tg: tg.create_task(...) is the preferred way to run tasks and cancel the rest if one fails. This is a short excerpt for agents, not a substitute for the Python standard library docs.', 'https://docs.python.org/3/library/asyncio-task.html', 'PSF-2.0', '34674350da81166cac5ac74242086ec7940ca8d0e0e41ec5e0df95a312d29de0', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('fastapi-path-query', 'fastapi', '0.115', 'Path and query parameters are declared in the function signature', 'In FastAPI, @app.get(''/items/{item_id}'') def read_item(item_id: int, q: str | None = None) treats item_id as a path parameter and q as an optional query parameter. Types are validated and documented in OpenAPI automatically. Use Query(), Path(), and Field() for constraints such as ge, le, min_length, and descriptions. This is a short excerpt for agents, not a substitute for the FastAPI tutorial.', 'https://fastapi.tiangolo.com/tutorial/path-params/', 'MIT', '6868ef525642222bc9cbec7fc95207c1c293bfdf06958cd679f5f96cff3056c3', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('fastapi-depends', 'fastapi', '0.115', 'Depends injects shared dependencies into a path operation', 'Declare a parameter as dep: Annotated[Type, Depends(provider)] so FastAPI calls provider, caches the result for the request, and injects it. Common uses are database sessions, current-user auth, and shared query parameters. A dependency can itself depend on others. Yield-based dependencies can run cleanup after the response. This is a short excerpt for agents, not a substitute for the FastAPI tutorial.', 'https://fastapi.tiangolo.com/tutorial/dependencies/', 'MIT', 'e71d1ab2e2e838d3b07b5970fbafb2f824ef4b6ed5aa24d925a2d7c707a5bcf3', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('fastapi-body-model', 'fastapi', '0.115', 'Pydantic models declare request and response bodies', 'Define a class Item(BaseModel) with typed fields and use it as a parameter (item: Item) to parse and validate the JSON request body, or as response_model to filter the response. Nested models and lists work as fields. Use model_config or Field() for examples and constraints. FastAPI generates the OpenAPI schema from the same models. This is a short excerpt for agents, not a substitute for the FastAPI tutorial.', 'https://fastapi.tiangolo.com/tutorial/body/', 'MIT', '5e7309b0c0a4e1eb3e897677e2bebeab594798977ef1867a1243431a2f94ec10', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('django-models', 'django', '5.2', 'A Model maps a Python class to a database table', 'class Book(models.Model) with fields such as models.CharField(max_length=200), ForeignKey, and ManyToManyField defines a table. Each model has an implicit AutoField primary key named id unless you set primary_key=True. makemigrations and migrate create and apply schema changes. Meta.ordering, db_table, and unique_together (or UniqueConstraint) configure the model. This is a short excerpt for agents, not a substitute for the Django docs.', 'https://docs.djangoproject.com/en/5.2/topics/db/models/', 'BSD-3-Clause', '6612aee6e4c4018f801b3a6676285cc72baa69ec85fae03060e19016b6c083b5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('django-queryset', 'django', '5.2', 'QuerySets are lazy until you evaluate them', 'Book.objects.filter(title__icontains=''x'').exclude(published=False) returns a QuerySet that does not hit the database until you iterate it, slice it, or call list(), count(), or exists(). Use get() for a single row (it raises DoesNotExist or MultipleObjectsReturned). select_related and prefetch_related reduce JOIN/query counts. update() and delete() act in bulk. This is a short excerpt for agents, not a substitute for the Django docs.', 'https://docs.djangoproject.com/en/5.2/topics/db/queries/', 'BSD-3-Clause', '3d922382f338e598dde319024657b73d1cefac9334fb3d1a5cd25f3869517779', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('django-urls', 'django', '5.2', 'path() connects a URL pattern to a view', 'In urls.py, urlpatterns = [path(''articles/<int:pk>/'', views.article_detail, name=''article-detail'')] captures typed path converters and passes them as view kwargs. include() mounts another URLconf. A view is a function or class-based view (as_view()) that takes a request and returns an HttpResponse. reverse(''article-detail'', args=[pk]) or the {% url %} tag builds a URL from the name. This is a short excerpt for agents, not a substitute for the Django docs.', 'https://docs.djangoproject.com/en/5.2/topics/http/urls/', 'BSD-3-Clause', 'c8dc367788f590407e00db1877581d8f53427614ebeccc5609eed7eb1efa7507', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pandas-dataframe', 'pandas', '2.2', 'A DataFrame is a labeled two-dimensional table', 'pd.DataFrame(data, columns=..., index=...) builds a table of Series aligned on an index. df[''col''] selects a column, df.loc[labels] selects by label, and df.iloc[i] selects by position. read_csv, read_parquet, and to_csv / to_parquet are the usual I/O entry points. Use assign and copy when you need a new object; many operations return a copy rather than modifying in place. This is a short excerpt for agents, not a substitute for the pandas user guide.', 'https://pandas.pydata.org/docs/user_guide/dsintro.html', 'BSD-3-Clause', 'e8cfd24f6846e5d8314c52f623fc206f54c745796c21a62fc1a54c4ada2f6474', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pandas-groupby', 'pandas', '2.2', 'groupby splits, applies, and combines', 'df.groupby(''key'').agg({''value'': ''sum''}) splits rows by key, applies an aggregation, and combines the result with the group keys as the index. Use as_index=False to keep keys as columns. groupby also supports .sum(), .mean(), .size(), .transform() (same shape as the input), and .apply(). Passing a list of keys creates a MultiIndex. This is a short excerpt for agents, not a substitute for the pandas user guide.', 'https://pandas.pydata.org/docs/user_guide/groupby.html', 'BSD-3-Clause', '16b35f8a78fd9b0cbe905780a8e5ec159e506b96ded6c40d0fb87e432699113c', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pandas-merge', 'pandas', '2.2', 'merge joins DataFrames on columns or indexes', 'pd.merge(left, right, on=''id'', how=''inner'') performs SQL-style joins. how can be ''inner'', ''left'', ''right'', or ''outer''. Use left_on and right_on when the key names differ, and suffixes when overlapping column names need renaming. concat stacks objects along an axis; join is a convenient index-based merge on the caller. This is a short excerpt for agents, not a substitute for the pandas user guide.', 'https://pandas.pydata.org/docs/user_guide/merging.html', 'BSD-3-Clause', '32785c8db981f1f0fdd04bdbba8113d3157e11a9f0085833f54d063fa563f079', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('numpy-ndarray', 'numpy', '2.1', 'ndarray is a typed, fixed-shape N-dimensional array', 'np.array([[1, 2], [3, 4]], dtype=np.float64) builds an ndarray. arr.shape, arr.dtype, and arr.ndim describe it. np.zeros, np.ones, np.arange, and np.linspace construct new arrays. Vectorized operators and ufuncs (np.sin, np.sum, np.mean) run over the whole array without Python loops. This is a short excerpt for agents, not a substitute for the NumPy user guide.', 'https://numpy.org/doc/stable/user/basics.html', 'BSD-3-Clause', '40d263b86d867d047f4dba9f0eb0628631ac73612b3be495d58afa96e129a90e', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('numpy-broadcasting', 'numpy', '2.1', 'Broadcasting aligns array shapes for elementwise ops', 'NumPy compares shapes from the trailing dimension forward. Dimensions are compatible if they are equal or one of them is 1; a missing dimension is treated as 1. So a (3, 1) array plus a (1, 4) array yields a (3, 4) result. Use arr[:, None] or np.newaxis to insert a length-1 axis. Broadcasting avoids explicit tiles and copies when it can. This is a short excerpt for agents, not a substitute for the NumPy user guide.', 'https://numpy.org/doc/stable/user/basics.broadcasting.html', 'BSD-3-Clause', 'de3a9854ddaec192083f3ca327e5f1d8007ed4aa7506e2f079907c730b1d5f81', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('numpy-indexing', 'numpy', '2.1', 'Integer, slice, and boolean indexing select arrays', 'arr[0, :3] uses basic slicing and returns a view when possible. Integer array indexing and boolean masks (arr[arr > 0]) produce copies. arr[..., 0] uses an ellipsis to fill missing axes. Combine slices with np.ix_ or mesh-style indexing to take a sub-grid. Prefer views for large data when you do not need a copy. This is a short excerpt for agents, not a substitute for the NumPy user guide.', 'https://numpy.org/doc/stable/user/basics.indexing.html', 'BSD-3-Clause', '652fbb28b859a76239d530e0298f6f650747586af9472a0e0729a92eaa171761', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('prisma-schema-model', 'prisma', '6.x', 'models in schema.prisma define tables and relations', 'A Prisma model is declared in schema.prisma: model User { id String @id @default(cuid()) email String @unique posts Post[] }. Relations use typed fields plus @relation on the foreign-key side. Run prisma migrate dev to create SQL migrations and prisma generate to refresh Prisma Client. Scalar types include String, Int, Boolean, DateTime, Json, and Decimal. This is a short excerpt for agents, not a substitute for the Prisma docs.', 'https://www.prisma.io/docs/orm/prisma-schema/data-model/models', 'Apache-2.0', 'bababf6f02c619c7c320349bb2f2e5be14e885d7341411036f6d29deaa23e669', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('prisma-crud', 'prisma', '6.x', 'Prisma Client findMany, create, and update are typed CRUD helpers', 'const users = await prisma.user.findMany({ where: { email: { contains: ''@'' } }, include: { posts: true }, orderBy: { createdAt: ''desc'' }, take: 20 }) returns typed objects. create, update, upsert, and delete accept a data object. findUnique requires a unique field. select and include control the returned shape. This is a short excerpt for agents, not a substitute for the Prisma docs.', 'https://www.prisma.io/docs/orm/prisma-client/queries/crud', 'Apache-2.0', '4ad3fe0932a80e504c75913d49b79a89d994b1ea1f44e26fd24b1dc0d19d616f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('prisma-transactions', 'prisma', '6.x', 'interactive transactions run several writes atomically', 'await prisma.$transaction(async (tx) => { ... }) starts an interactive transaction. Use the tx client for every query inside the callback so they share one database transaction; throwing rolls it back. For a known list of operations, prisma.$transaction([prisma.user.create(...), prisma.post.update(...)]) is the sequential (batch) form. Set isolationLevel when you need a stricter isolation mode. This is a short excerpt for agents, not a substitute for the Prisma docs.', 'https://www.prisma.io/docs/orm/prisma-client/queries/transactions', 'Apache-2.0', '05a6e7cb7f660c38cb6756fb098ea56fc15363580bc5ae47d7a307550677e298', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vite-define-config', 'vite', '6.x', 'defineConfig types the Vite config object', 'vite.config.ts typically export default defineConfig({ plugins: [react()], root, build: { outDir, target }, server: { port, proxy } }). defineConfig provides TypeScript hints and can receive a function ({ command, mode }) so the config can change between serve and build. ESM is the default config format. This is a short excerpt for agents, not a substitute for the Vite guide.', 'https://vite.dev/config/', 'MIT', 'bd8c359d3947f78dfebff5c906aff121bf9deeda95166a0ba848a0b877cbe7cb', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vite-env', 'vite', '6.x', 'only VITE_ prefixed env vars are exposed to client code', 'Vite loads .env, .env.local, .env.[mode], and .env.[mode].local. Only variables prefixed with VITE_ are exposed to source as import.meta.env.VITE_*. Other keys stay on the server side of the config and must not be inlined into the client bundle. import.meta.env.MODE, BASE_URL, PROD, and DEV are always available. This is a short excerpt for agents, not a substitute for the Vite guide.', 'https://vite.dev/guide/env-and-mode.html', 'MIT', '36fc104a7cc99ca1ee0a0990adad665bcfe3be08c3ea5699c19d1b96fe0d02a8', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vite-plugins', 'vite', '6.x', 'Vite plugins hook into serve, build, and HMR', 'A Vite plugin is a Rollup-compatible plugin plus Vite-specific hooks such as config, configureServer, transformIndexHtml, and handleHotUpdate. Put plugins in the plugins array of the config. Official plugins include @vitejs/plugin-react and @vitejs/plugin-vue. Plugin order matters; enforce: ''pre'' | ''post'' controls when a hook runs. This is a short excerpt for agents, not a substitute for the Vite guide.', 'https://vite.dev/guide/api-plugin.html', 'MIT', '853fa45a71d5a052853dbd4740b3abf6c018641967b515bf8e94f98783b44e00', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('requests-get', 'requests', '2.32', 'requests.get sends an HTTP GET and decodes the response', 'import requests; r = requests.get(url, params={''q'': ''x''}, timeout=10). r.status_code, r.headers, r.text, and r.json() read the result. r.raise_for_status() throws HTTPError for 4xx/5xx. Pass json= or data= on post/put to send a body, and headers= for custom headers. Always set a timeout. This is a short excerpt for agents, not a substitute for the Requests user guide.', 'https://requests.readthedocs.io/en/latest/user/quickstart/', 'Apache-2.0', 'e5e3e8e964d2201957855232476543c9b1b34b08e4be8bfa0dab0f50eb936753', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('requests-session', 'requests', '2.32', 'a Session persists cookies and connection pooling', 'with requests.Session() as s: s.headers.update({''User-Agent'': ''...''}); s.get(url) reuses TCP connections via urllib3 and persists cookies across requests. Set s.auth, s.proxies, or s.verify on the session so every request inherits them. A session is the right default when you call an API more than once. This is a short excerpt for agents, not a substitute for the Requests user guide.', 'https://requests.readthedocs.io/en/latest/user/advanced/', 'Apache-2.0', '53965d94fa25897cd3fddf4d079e2de21ccd076c5f1ace381a3c091160f09bb8', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pydantic-basemodel', 'pydantic', '2.10', 'BaseModel validates and serializes typed data', 'class User(BaseModel): name: str; age: int = Field(ge=0). User(name=''Ada'', age=12) validates types and constraints and raises ValidationError on failure. model_dump() returns a dict; model_dump_json() returns JSON. model_config = ConfigDict(extra=''forbid'') rejects unknown fields. Use Field() for aliases, defaults, and descriptions. This is a short excerpt for agents, not a substitute for the Pydantic docs.', 'https://docs.pydantic.dev/latest/concepts/models/', 'MIT', 'a871355fe7508568304ef0a48717d38e25e37afaddcc23995074b9b8cb58c9f5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pydantic-model-validate', 'pydantic', '2.10', 'model_validate parses objects; model_validate_json parses strings', 'In Pydantic v2, Model.model_validate(data) validates a dict or object, and Model.model_validate_json(s) validates a JSON string. Use TypeAdapter(list[Model]).validate_python(items) for types that are not a BaseModel subclass. The v1 parse_obj / parse_raw aliases still exist for compatibility but model_validate is the v2 API. This is a short excerpt for agents, not a substitute for the Pydantic docs.', 'https://docs.pydantic.dev/latest/concepts/models/', 'MIT', '82a2f07439ace2edf2411fd7ea569f2a27f2956f30ff04db85f239d9b72bcaa5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pydantic-field-validator', 'pydantic', '2.10', 'field_validator and model_validator customize checks', '@field_validator(''email'') classmethod def check_email(cls, v: str) -> str: runs after type coercion for that field. @model_validator(mode=''after'') def check(self): can compare fields on the already-built model; mode=''before'' receives the raw input. Annotated[..., AfterValidator(fn)] attaches a validator without a method. This is a short excerpt for agents, not a substitute for the Pydantic docs.', 'https://docs.pydantic.dev/latest/concepts/validators/', 'MIT', 'dca92484645eb73f2d231d0edb7f13a8216bcbdce67d2b35028810cc5dea0fca', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('flask-routing', 'flask', '3.1', 'app.route binds a URL to a view function', 'app = Flask(__name__); @app.route(''/user/<int:id>'') def user(id): return ... registers a view. Variable rules support string, int, float, path, and uuid converters. methods=[''POST''] allows other verbs. request.args, request.form, request.get_json(), and request.files read the incoming request. jsonify() or a string becomes the response. This is a short excerpt for agents, not a substitute for the Flask docs.', 'https://flask.palletsprojects.com/en/stable/quickstart/', 'BSD-3-Clause', 'f5b3948361d79eee41227bd2d81a2a0bc9983cea21a9a884c6767288bbbe3904', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('flask-blueprints', 'flask', '3.1', 'Blueprints split an app into reusable route groups', 'bp = Blueprint(''auth'', __name__, url_prefix=''/auth'') then @bp.route(''/login'') defines routes that stay unregistered until app.register_blueprint(bp). Blueprints can have their own templates, static folders, and error handlers. They are the usual way to split a Flask project into packages. This is a short excerpt for agents, not a substitute for the Flask docs.', 'https://flask.palletsprojects.com/en/stable/blueprints/', 'BSD-3-Clause', '44ef96dccfb2b2903bf4bd6edd5cd8e350102f518b624fa14805c1cadfa51ee5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pg-jsonb', 'postgresql', '17', 'jsonb stores JSON in a decomposed binary form', 'PostgreSQL jsonb is a binary JSON type that supports indexing and operators: doc -> ''key'' returns JSON, doc ->> ''key'' returns text, and doc @> ''{"a": 1}''::jsonb tests containment. GIN indexes on jsonb_path_ops or jsonb_ops speed containment queries. jsonb_set, jsonb_build_object, and jsonb_array_elements are common helpers. Prefer jsonb over json when you will query inside the document. This is a short excerpt for agents, not a substitute for the PostgreSQL docs.', 'https://www.postgresql.org/docs/current/datatype-json.html', 'PostgreSQL', '90fef24fba531109d4679a1240c5880bd1f2b9bba1684056bd982fdf3a59a667', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pg-cte', 'postgresql', '17', 'WITH clauses define common table expressions', 'WITH regional AS (SELECT ... FROM sales GROUP BY region) SELECT * FROM regional WHERE total > 1000 names a subquery you can reference later in the same statement. WITH RECURSIVE walks a tree or graph. INSERT/UPDATE/DELETE can appear in a CTE and return rows to the main statement. MATERIALIZED / NOT MATERIALIZED controls whether the CTE is computed once. This is a short excerpt for agents, not a substitute for the PostgreSQL docs.', 'https://www.postgresql.org/docs/current/queries-with.html', 'PostgreSQL', '227161da60db19a41fadd8bd25dc898f2617fb8d3872306e8c564c15291c8ed4', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('pg-indexes', 'postgresql', '17', 'B-tree is the default index; GIN and GiST cover other types', 'CREATE INDEX ON table (col) builds a B-tree, which is the right default for equality and range comparisons. Use UNIQUE, INCLUDE (covering columns), and partial indexes (WHERE ...) when they shrink the index. GIN is typical for jsonb, arrays, and full-text; GiST for geometric and range types; BRIN for very large append-mostly tables. EXPLAIN ANALYZE shows whether a query uses an index. This is a short excerpt for agents, not a substitute for the PostgreSQL docs.', 'https://www.postgresql.org/docs/current/indexes-intro.html', 'PostgreSQL', '81a46ad7104ea193613a4f199dcb014663376492f028ff013a732fb4211011bb', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('docker-dockerfile', 'docker', 'docs-2026-11', 'FROM, RUN, COPY, and CMD are the core Dockerfile instructions', 'A Dockerfile starts with FROM <image> and then layers RUN (execute a command), COPY or ADD (add files), WORKDIR, ENV, EXPOSE, USER, ENTRYPOINT, and CMD. Each RUN creates a layer, so combine related commands and put frequently changing COPY steps later to improve cache hits. CMD is the default command; ENTRYPOINT is the executable. This is a short excerpt for agents, not a substitute for the Docker docs.', 'https://docs.docker.com/reference/dockerfile/', 'Apache-2.0', '0d490865cb9ec15031b91ca6d7279cd770d732292e0d75c4e974d486095b9457', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('docker-multistage', 'docker', 'docs-2026-11', 'Multi-stage builds copy artifacts from a builder image', 'A multi-stage Dockerfile uses several FROM lines, optionally named with AS builder. Later stages can COPY --from=builder /app/bin /usr/local/bin so compilers, caches, and dev dependencies never land in the final image. You can also COPY --from=anotherimage or --from=0 (the first stage). This is the usual way to ship a small runtime image. This is a short excerpt for agents, not a substitute for the Docker docs.', 'https://docs.docker.com/build/building/multi-stage/', 'Apache-2.0', '5b75c53b94637b90326a1dd9cf98628de958a6308efad452eb74dd4e85d7b014', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('docker-compose', 'docker', 'docs-2026-11', 'Compose YAML defines services, networks, and volumes', 'A compose.yaml file lists services under services:, each with an image or build context, ports, environment, volumes, and depends_on. docker compose up starts the project; down stops and removes it. Named volumes persist data; networks isolate service DNS (the service name is the hostname). Use profiles and multiple compose files to vary environments. This is a short excerpt for agents, not a substitute for the Docker docs.', 'https://docs.docker.com/compose/', 'Apache-2.0', '2c1ca1f36cae0c8ebd79c787975847845c83c3522920fd1c71bc9ce84ef8804b', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('stripe-payment-intent', 'stripe', 'v1', 'PaymentIntents create and confirm a payment', 'Stripe''s Payment Intents API collects a payment in two steps: create a PaymentIntent on your server, then confirm it. POST /v1/payment_intents with amount (in the smallest currency unit) and currency. Setting confirm=true creates and confirms in one call and accepts the Confirm API parameters. Reuse one PaymentIntent for a cart or checkout session instead of creating a new one after an interruption. Pass the client_secret to the client; do not send the whole PaymentIntent object or secret keys to the browser. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.stripe.com/payments/payment-intents', 'proprietary', '339b9d8290f6063e130401d10214abbe7fb198bb194b4164a134618bb9fe0e06', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('stripe-idempotency-key', 'stripe', 'v1', 'Idempotency-Key makes Stripe POSTs safely retryable', 'Stripe v1 POST requests accept an Idempotency-Key so a retried create or update does not run twice. Generate a unique key (a v4 UUID is recommended), at most 255 characters, and avoid putting emails or other personal data in the key. Stripe stores the first response for that key; later retries with the same key and the same parameters return the saved result, including 500s. If the parameters differ, the request errors. Keys can be pruned after 24 hours. Do not send idempotency keys on GET or DELETE. Use a key derived from the cart or session id when creating a PaymentIntent so a checkout retry cannot open a second intent. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.stripe.com/api/idempotent_requests', 'proprietary', 'ad379991e575fb01767aad659dded272be829837406d40b8548ff5f28be6f217', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('stripe-webhook-verify', 'stripe', 'v1', 'Verify Stripe webhooks with Stripe-Signature', 'Stripe delivers events to your HTTPS webhook endpoint as a JSON POST. Verify each event before acting: check the Stripe-Signature header with the raw request body and the endpoint''s whsec_ signing secret, preferably through an official Stripe library. Do not parse the body into JSON before verification, or the signature will not match. Return a 2xx quickly, then do slower fulfillment work. Events can arrive more than once; record processed event ids and ignore duplicates. Unsigned or failed signatures must be rejected so attackers cannot fake a successful payment. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.stripe.com/webhooks', 'proprietary', '358ab78a77df23cecb0d4133185b82f77e6af1fd667c61323223c0ed669cd11e', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('stripe-fulfill-succeeded', 'stripe', 'v1', 'Fulfill orders on payment_intent.succeeded', 'Fulfill goods or services from the payment_intent.succeeded webhook, not from client-side success callbacks. A customer can close the tab after paying and before your frontend runs. Listen for payment_intent.succeeded to fulfill and payment_intent.payment_failed to ask for another method. A PaymentIntent can have more than one Charge if the customer retried. Polling the PaymentIntent can hit rate limits and is less reliable than webhooks. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.stripe.com/payments/payment-intents/verifying-status', 'proprietary', '521795ec23e6e743336b4bd8d5a5d80d36c608a30729d25439b563d8b975a599', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('openai-responses-api', 'openai', 'v1', 'Responses API is recommended for new OpenAI projects', 'OpenAI recommends the Responses API (POST /v1/responses) for new projects. Chat Completions remains supported. Responses uses input and output arrays of typed Items instead of a messages array; a message is one Item type, alongside function_call, function_call_output, and reasoning. You get one generation (there is no n/choices parameter). When you only need the final text, SDKs expose an output_text helper. To disable stored responses, set store: false. This is a short original summary for agents, not a substitute for the official API reference.', 'https://developers.openai.com/api/docs/guides/migrate-to-responses', 'proprietary', '8f271dfc5640baae67ca986e96da2e31fc5093a66aacfafe8c9e3259afc04bfb', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('openai-structured-outputs', 'openai', 'v1', 'Structured Outputs bind the model to a JSON Schema', 'Structured Outputs constrains completed, non-refusal model output to a JSON Schema you supply. Prefer json_schema over the older json_object mode, which only guarantees valid JSON, not schema adherence. In the Responses API, pass the schema with text.format. In Chat Completions, pass response_format with type json_schema and a json_schema object (set strict to true). You still must handle refusals, incomplete responses, and API errors, and enforce business rules the schema does not express. This is a short original summary for agents, not a substitute for the official API reference.', 'https://developers.openai.com/api/docs/guides/structured-outputs', 'proprietary', '1049d40880a38c22007e22f2fe1ae3db3164f1c13ab625859913939204df43a2', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('openai-response-state', 'openai', 'v1', 'Chain Responses with previous_response_id', 'Unlike Chat Completions, where your app must resend the full messages array each turn, the Responses API can carry conversation state for you. Pass previous_response_id to chain the next turn onto a stored response, or use the Conversations API for a longer-lived thread. Set store: false if you do not want responses stored. System or developer guidance can go in a developer input item or in the top-level instructions field for a single turn. This is a short original summary for agents, not a substitute for the official API reference.', 'https://developers.openai.com/api/docs/guides/migrate-to-responses', 'proprietary', '30746e584e254a74ab474ba3dfe4498cdcba599ee55aa1634301edda902b68cd', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('openai-function-calling-items', 'openai', 'v1', 'Responses function calls are typed Items with call_id', 'On the Responses API, a model tool call arrives as a function_call output Item, not as a Chat Completions message with tool_calls. After your app runs the tool, send a function_call_output input Item linked to that call with the same call_id. Keep Items separate rather than gluing tool calls and text into one message object. Function configuration also differs from Chat Completions; follow the function-calling guide when migrating. This is a short original summary for agents, not a substitute for the official API reference.', 'https://developers.openai.com/api/docs/guides/migrate-to-responses', 'proprietary', '471e2540810c89fb7a7c36c7e06058d45854ee555dd9c8b38e0b234429ffa7e4', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('langchain-create-agent', 'langchain', '1.1', 'create_agent is the LangChain agent harness', 'In current LangChain, create_agent (from langchain.agents) is the standard way to build an agent. An agent is a model calling tools in a loop; the harness is the prompt, tools, and middleware around that loop. Pass a model (a chat model instance or a string such as openai:gpt-4.1), an optional tools list, and an optional system_prompt. The returned object is a compiled graph. Invoke it with a messages dict: agent.invoke({"messages": [{"role": "user", "content": "..."}]}). This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.langchain.com/oss/python/langchain/agents', 'MIT', '75d0749e74483e8f2b68e0019f4029229e1c164cbefcc8c8936a6c76efe07fd5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('langchain-agent-loop', 'langchain', '1.1', 'create_agent loops tools until the model stops calling them', 'create_agent builds a graph that sends the message list (after applying system_prompt) to the model. If the AIMessage contains tool_calls, the tools node runs those tools and appends ToolMessage results, then the model is called again. The loop stops when the model returns no tool_calls, and the graph returns the full message list. If tools is None or empty, the graph is a single model node with no tool loop. You can also pass response_format for structured output and checkpointer for state. This is a short original summary for agents, not a substitute for the official API reference.', 'https://reference.langchain.com/python/langchain/agents/factory/create_agent', 'MIT', '8fb601d200dcaf8e51e7d56be7001139e2eb045e36ff7d33f27e9f2a0ded7d49', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('langchain-chat-openai', 'langchain', '1.1', 'ChatOpenAI lives in langchain-openai', 'The OpenAI chat integration is langchain_openai.ChatOpenAI, installed with pip install -U langchain-openai. Construct it with model (and optional api_key, base_url, temperature, timeout, max_retries). You can pass that instance into create_agent, or skip the class and pass a model string such as openai:gpt-4.1. ChatOpenAI can point at an OpenAI-compatible base_url, but it only follows official OpenAI API shapes; non-standard fields from third-party providers are not preserved, so use a provider-specific package when you need those features. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.langchain.com/oss/python/integrations/chat/openai', 'MIT', '5b422447beb97aa522ac3800d47ba3ad6e6ae3f2a5318dbd848554132e84a945', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('langchain-init-model-string', 'langchain', '1.1', 'create_agent accepts a provider:model string', 'The model argument to create_agent can be a string identifier such as openai:gpt-4.1 or a BaseChatModel instance. String identifiers are resolved through LangChain''s model initialization helpers (see init_chat_model). This lets you swap providers without constructing a vendor class first. Tools may be BaseTool objects, plain Python callables, or dicts. Keep the system prompt in system_prompt rather than prepending a SystemMessage yourself unless you already have one. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.langchain.com/oss/python/langchain/overview', 'MIT', 'faac34b3c0232070cd8cf0c6d0fe58fa32f23038767d2acad8108cfe9f1d2ac9', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('aws-sdk-js-modular-clients', 'aws-sdk', '3.x', 'AWS SDK for JavaScript v3 uses per-service clients', 'AWS SDK for JavaScript v3 is modular. Install and import only the service client you need, for example import { S3Client, ListBucketsCommand } from "@aws-sdk/client-s3". Create a client with new S3Client({ region: "us-east-1" }) and call await client.send(new ListBucketsCommand({})). This replaces the v2 pattern of new AWS.S3().listBuckets(). Each command is a class; pass input as the constructor argument. Clients are the public surface; do not expect a single aws-sdk package to include every service. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/sdk-for-javascript/v3/developer-guide/welcome.html', 'Apache-2.0', 'ec37f0353c394dd4837c412daa8cbca8dc17a9c6c3bcd91f62e8decc7b8952a1', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('aws-sdk-js-fromini', 'aws-sdk', '3.x', 'fromIni loads shared AWS credentials in SDK v3', 'In AWS SDK for JavaScript v3, load shared-file credentials with fromIni from @aws-sdk/credential-providers (Apache-2.0). import { fromIni } from "@aws-sdk/credential-providers" and pass credentials: fromIni() to the client. It reads ~/.aws/credentials and ~/.aws/config (or AWS_SHARED_CREDENTIALS_FILE). Optional arguments include profile, filepath, and configFilepath. If the client is constructed with profile, fromIni inherits that profile unless you override it. fromIni is not available in browsers. Prefer the default provider chain when running on AWS with instance or task roles. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/sdk-for-javascript/v3/developer-guide/migrate-credential-providers.html', 'Apache-2.0', 'a979e16eb985060ac7ba12b707ecb419221a00939889ffd4becc651c6b4ce14e', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('aws-sdk-js-commands', 'aws-sdk', '3.x', 'v3 clients send Command objects, not callback methods', 'AWS SDK for JavaScript v3 clients expose send(command) and return promises. There is no callback-style service.method(params, cb) on the v3 client. Import the command for the API you want (GetObjectCommand, PutObjectCommand, ListBucketsCommand) from the same client package, construct it with the input shape, and await client.send(command). Mid-stack errors are thrown as exceptions. Configure retries and region on the client, not on each command, unless you pass a specific override. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/sdk-for-javascript/v3/developer-guide/welcome.html', 'Apache-2.0', 'bfc784e7e734aa5aed04c40c8af5037f90248eddb7cc864314d5971e97fd34ac', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('boto3-client-and-session', 'boto3', '1.44', 'boto3.client and Session create service clients', 'In boto3, boto3.client("s3", region_name="us-east-1") returns a low-level service client. boto3.Session(profile_name="my-profile", region_name="us-west-2") stores credentials and region so you can call session.client("s3") or session.resource("s3") with the same config. session.client(service_name) is the usual starting point for a named AWS API. Pass endpoint_url only when you need a custom endpoint. Do not hard-code access keys in source; let the session load the environment or the shared credentials file. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/boto3/latest/guide/credentials.html', 'Apache-2.0', '695f84f62c9d5e3bbfd6a15cce14e5e777fb16894a0db317b008e3302419e78f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('boto3-credential-chain', 'boto3', '1.44', 'boto3 loads credentials from the standard AWS chain', 'boto3 and botocore resolve credentials in a chain: parameters you pass to Session or client, then environment variables (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_SESSION_TOKEN when present), then the shared credentials and config files, then IAM roles for Amazon EC2 or container credentials. You can pass aws_access_key_id and aws_secret_access_key into client() or Session() for temporary or externally sourced keys, including an aws_session_token from STS. Official docs warn against hard-coding keys. Prefer a named profile or a runtime role. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/boto3/latest/guide/credentials.html', 'Apache-2.0', 'ed49d9c957bba77f360379d297ca6baf216283ed6e018a5c2ec77c06a8882251', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('boto3-session-profiles', 'boto3', '1.44', 'Use a boto3 Session to select a profile and region', 'boto3.session.Session accepts profile_name, region_name, and optional explicit keys or a session token. If profile_name is omitted, the default profile is used. Create clients from the session so they share that profile and region: session = boto3.Session(profile_name="my-profile", region_name="us-east-1"); s3 = session.client("s3"). available_profiles lists profiles the session can see. A region passed directly to client() overrides the session default for that client only. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.aws.amazon.com/boto3/latest/reference/core/session.html', 'Apache-2.0', '3745ecc9e18caa5652d44066c9deff2fda845ddc8689a8d871400bb36882a46d', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('x402-v2-payment-headers', 'x402', '2.32', 'x402 v2 uses PAYMENT-REQUIRED, PAYMENT-SIGNATURE, and PAYMENT-RESPONSE headers', 'In x402 v2 a server answers an unpaid request with HTTP 402 and a PAYMENT-REQUIRED header holding a base64-encoded PaymentRequired object (accepted schemes, price, network, payTo). The client retries with a PAYMENT-SIGNATURE header holding a base64-encoded PaymentPayload. After settlement the server returns a PAYMENT-RESPONSE header with a base64-encoded SettlementResponse, whether settlement succeeded or failed. All three header values are base64 JSON. The exact and upto schemes usually settle in the same round trip; batch-settlement redeems later. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.x402.org/core-concepts/http-402', 'Apache-2.0', 'bf397da8b6bb47d33a66a803d62a71e400e1dbe574df682ac2ea39f4ca16d2f9', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('x402-v2-fetch-client-solana', 'x402', '2.32', 'Pay x402 endpoints from Node with @x402/fetch and a Solana signer', 'Install @x402/fetch plus @x402/svm (and @x402/evm for Base). Create a signer with createKeyPairSignerFromBytes from @solana/kit using a 64-byte secret key loaded from the environment, then: const client = new x402Client(); client.register("solana:*", new ExactSvmScheme(svmSigner)); const fetchWithPayment = wrapFetchWithPayment(fetch, client). x402Client comes from @x402/core/client and ExactSvmScheme from @x402/svm/exact/client. fetchWithPayment handles the 402, signs, and retries. new x402HTTPClient(client).processResponse(res) reports paymentStatus (settled or settle_failed). By default the client only pays USD-pegged assets such as USDC and caps each payment at $1. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.x402.org/getting-started/quickstart-for-buyers', 'Apache-2.0', '4ed25007a70cc201c5f3065ca9fd3cf8f2fcb55d0939271c61145827d008e19d', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('x402-v2-express-seller', 'x402', '2.32', 'Protect an Express route with x402 v2 paymentMiddleware', 'Install @x402/express, @x402/core, and the mechanism packages you accept (@x402/evm, @x402/svm). Build new HTTPFacilitatorClient({ url }) from @x402/core/server, then app.use(paymentMiddleware({ "GET /weather": { accepts: [{ scheme: "exact", price: "$0.001", network: "solana:EtWTRABZaYq6iMfeYKouRu166VU2xqa1", payTo: svmAddress }], description, mimeType: "application/json" } }, new x402ResourceServer(facilitatorClient).register("solana:EtWTRABZaYq6iMfeYKouRu166VU2xqa1", new ExactSvmScheme()))). ExactSvmScheme here is imported from @x402/svm/exact/server. Hono, Next.js (paymentProxy or withX402), and Fastify packages follow the same shape. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.x402.org/getting-started/quickstart-for-sellers', 'Apache-2.0', '6416bbade99ed782fee771e566dcf7e364820df87a13eac9c8b06465242e52dc', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('x402-v2-mainnet-networks', 'x402', '2.32', 'x402 v2 network ids (CAIP-2) and mainnet facilitators', 'x402 v2 names networks in CAIP-2 form: Base mainnet eip155:8453, Base Sepolia eip155:84532, Solana mainnet solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp, Solana devnet solana:EtWTRABZaYq6iMfeYKouRu166VU2xqa1. The x402.org facilitator (https://x402.org/facilitator) is for testnets only; do not use it for mainnet routes. For mainnet, point HTTPFacilitatorClient at a production facilitator such as the Coinbase CDP URL or PayAI (https://facilitator.payai.network), switch the network ids, and use a real mainnet payTo address. Test with small amounts first. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.x402.org/getting-started/quickstart-for-sellers', 'Apache-2.0', '2a1db18cf08f8ef88613ba1c13f0baabc2d355d074802dc1b8b27a51e8ed63c5', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('x402-v2-python-httpx', 'x402', '2.29 (Python)', 'Pay x402 endpoints from Python with x402HttpxClient', 'Install pip install "x402[httpx]" and add "x402[svm]" for Solana. Create client = x402Client() (from x402), register a scheme such as register_exact_svm_client(client, KeypairSigner.from_base58(os.getenv("SVM_PRIVATE_KEY"))) from x402.mechanisms.svm, or register_exact_evm_client with an EthAccountSigner for EVM. Then async with x402HttpxClient(client) as http: response = await http.get(url). The client handles the 402 challenge and retry. x402HTTPClient(client).get_payment_settle_response(lambda name: response.headers.get(name)) decodes the settlement header. A requests-based client exists for sync code via "x402[requests]". This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.x402.org/getting-started/quickstart-for-buyers', 'Apache-2.0', 'db86673a84ac04b6ae1ff5f42d5af253198993a8c484c117bfd5b97e515ffb8f', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-kit-create-client', 'solana-kit', '8.6', 'Create a Solana Kit client with RPC, signer, and program plugins', 'Kit is the JavaScript SDK for Solana apps on Node, web, and React Native. Install @solana/kit with @solana/kit-plugin-rpc and @solana/kit-plugin-signer, plus program plugins like @solana-program/system and @solana-program/token. Build a client by chaining plugins: await createClient().use(signerFromFile("~/.config/solana/id.json")).use(solanaMainnetRpc({ rpcUrl: "https://api.mainnet.solana.com" })).use(systemProgram()).use(tokenProgram()). The client then exposes client.rpc.getBalance(address).send(), client.system.instructions.transferSol(...), client.token.accounts.mint.fetch(address), and client.sendTransaction(instructions). A no-client mode imports only the functions you need for maximum tree-shaking. This is a short original summary for agents, not a substitute for the official API reference.', 'https://www.solanakit.com/docs', 'MIT', '55dd2c36e80425febf8ba7158e68bac83847b199f2df8b033b5bddfb0fe89dfd', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-kit-rpc-and-address', 'solana-kit', '8.6', 'Solana Kit RPC calls return a request you must .send()', 'In @solana/kit, createSolanaRpc(url) returns an RPC object and createSolanaRpcSubscriptions(wsUrl) a subscriptions object. Cluster helpers like devnet(url) brand the URL for a cluster. Addresses are branded strings made with address("...base58..."), and SOL amounts use lamports(10_000_000n) bigints. Each RPC method builds a request that runs only when you call .send(), for example await rpc.getBalance(address("...")).send(). airdropFactory({ rpc, rpcSubscriptions }) returns an airdrop function that works only on test clusters. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/anza-xyz/kit/tree/main/packages/kit', 'MIT', '859050e874296d3bd72696c3a45b9a9626d3d195ad85c9912b08e48a6ed5fbde', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-kit-send-and-confirm', 'solana-kit', '8.6', 'Send and confirm a transaction with sendAndConfirmTransactionFactory', 'sendAndConfirmTransactionFactory({ rpc, rpcSubscriptions }) from @solana/kit returns a function that sends a blockhash-based transaction and waits for confirmation: await sendAndConfirmTransaction(transaction, { commitment: "confirmed" }). Catch expiry with isSolanaError(e, SOLANA_ERROR__BLOCK_HEIGHT_EXCEEDED), which means the blockhash expired. Use sendAndConfirmDurableNonceTransactionFactory for nonce-based transactions and sendTransactionWithoutConfirmingFactory when you do not want to wait. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/anza-xyz/kit/tree/main/packages/kit', 'MIT', '8a08320e3894e4a9cd59ad21192d34633648159c6bb43d7d15048f320a82f268', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-kit-compute-unit-limit', 'solana-kit', '8.6', 'Estimate and set a compute unit limit in Solana Kit', 'Without an explicit compute unit limit, validators assume 200K CU per instruction, and tight limits make inclusion more likely. In @solana/kit, estimateComputeUnitLimitFactory({ rpc }) returns an estimator that simulates the message (temporarily at the 1,400,000 max) and returns units consumed; apply it with setTransactionMessageComputeUnitLimit(estimate, message). estimateAndSetComputeUnitLimitFactory(estimator) sets it in one step and leaves explicit limits unchanged; pair it with fillTransactionMessageProvisoryComputeUnitLimit to reserve space during construction. Estimates can be off, so consider adding a margin. For unsigned transactions headed to a wallet, the wallet may set the limit. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/anza-xyz/kit/tree/main/packages/kit', 'MIT', '65dd3e56975e85ac144223077ce7db982761dc517d816e93b395fed318c474c6', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-web3js-v3-overview', 'solana-web3js', '3.2', '@solana/web3.js v3 keeps the class API but is rebuilt on Solana Kit', '@solana/web3.js v3 (latest on npm) keeps the familiar class-based API (Connection, PublicKey, Keypair, Transaction), updates it for current RPC methods, and rebuilds internals on Solana Kit. v1.x lives on the maintenance/v1.x branch and gets critical fixes only. v3 has breaking changes: async Keypair and signing flows, bigint amounts, Uint8Array instead of Buffer, readonly RPC results, and removed APIs. The maintainers ask agents not to downgrade to v1 and to read the v1-to-v3 migration guide first. Node 20.18.0 or newer is supported. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/solana-foundation/solana-web3.js', 'MIT', 'd984bede148b4ee72eda7920281df4002ecda0dca1d34f0fbaad8795700ba9e8', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-web3js-v3-async-keys', 'solana-web3js', '3.2', 'web3.js v3: Keypair, PDA, and signing calls are async', 'In @solana/web3.js v3 the Keypair constructor is no longer public. Use await Keypair.generate(), await Keypair.fromSecretKey(bytes), or await Keypair.fromSeed(seed). PDA helpers are async too: await PublicKey.findProgramAddress(...) and await PublicKey.createProgramAddress(...). Transaction signing is async: await transaction.sign(...), await transaction.partialSign(...), await versionedTransaction.sign(...). Mark callers async and move code that reads signatures or .publicKey after the awaited call. PublicKey.unique(), Account, and fee-calculator methods such as getRecentBlockhash were removed. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/solana-foundation/solana-web3.js/blob/main/docs/web3js-v1-to-v3-migration.md', 'MIT', '73adf7619db14ef495dd0a9f22cb927520891379babfcbd377737cd2ab607daf', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('solana-web3js-v3-connection-bigint', 'solana-web3js', '3.2', 'web3.js v3 Connection defaults to confirmed and returns bigint numerics', 'In @solana/web3.js v3, an omitted commitment defaults to confirmed rather than finalized, so set finalized explicitly if you need it. Many RPC numeric fields (lamports, slots, block heights, epochs) are bigint, and JSON.stringify throws on raw bigint without a replacer. Account data is Uint8Array, often wrapped in Readonly with space: bigint. RPC arrays are readonly, so clone before .sort() or .push(). Since v3.1.0, Connection implements Kit client interfaces, so you can pass a Connection to Kit APIs that take a client. PublicKey implements HasAddress for @solana-program/* clients, and toBase58() returns Kit''s branded Address string. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/solana-foundation/solana-web3.js/blob/main/docs/web3js-v1-to-v3-migration.md', 'MIT', '83c0de00bdb345db2ee918333f238cb35f674e7fb08dc3998e67f794cdbbd4a9', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-ts-v2-packages', 'mcp-typescript', '2.4', 'MCP TypeScript SDK v2 splits into @modelcontextprotocol/server and /client', 'The main branch of the MCP TypeScript SDK is v2, the stable line, implementing the 2026-07-28 MCP spec. It publishes @modelcontextprotocol/server and @modelcontextprotocol/client, plus thin middleware packages @modelcontextprotocol/node, /express, /fastify, and /hono. v1 ships as @modelcontextprotocol/sdk on the v1.x branch and gets bug and security fixes for at least six months after the v2 release on 2026-07-27. Tool schemas use Standard Schema, so Zod v4, Valibot, or ArkType all work. It runs on Node.js, Bun, and Deno. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/typescript-sdk', 'Apache-2.0', '3c755350048ad1454ad90ec0e6400421c4deaf3cde376249fcb851aa89e29404', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-ts-v2-register-tool', 'mcp-typescript', '2.4', 'Register a tool on an McpServer with the v2 TypeScript SDK', 'With @modelcontextprotocol/server: const server = new McpServer({ name: "greeting-server", version: "1.0.0" }); server.registerTool("greet", { description: "Greet someone by name", inputSchema: z.object({ name: z.string() }) }, async ({ name }) => ({ content: [{ type: "text", text: `Hello, ${name}!` }] })). Import z from "zod/v4". For stdio, connect with new StdioServerTransport() from @modelcontextprotocol/server/stdio: await server.connect(transport). This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/typescript-sdk', 'Apache-2.0', '033d2de4d3e0c0894a87617897da2f477fa489733385f3ee959a476fa244943a', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-ts-v2-web-standard', 'mcp-typescript', '2.4', 'Serve an MCP server on Cloudflare Workers, Deno, or Bun with createMcpHandler', 'createMcpHandler(() => { const server = new McpServer(...); server.registerTool(...); return server; }) from @modelcontextprotocol/server returns a { fetch } object, so export default handler mounts it on Cloudflare Workers, Deno, or Bun. The factory runs once per request. The handler does no Host or Origin validation, so guard it against DNS rebinding with hostHeaderValidationResponse(request, [hosts]) and originValidationResponse(request, [origins]) before calling handler.fetch(request). Pass verified auth as handler.fetch(request, { authInfo }); tools read it as ctx.http.authInfo. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/typescript-sdk/blob/main/docs/serving/web-standard.md', 'Apache-2.0', '23136927c0d806f7cbb72e6ee29de1766abe8d4fd097ec3bf13d1ecaedd63334', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-ts-v2-client-connect', 'mcp-typescript', '2.4', 'Connect an MCP client over Streamable HTTP with the v2 SDK', 'With @modelcontextprotocol/client: const client = new Client({ name: "my-client", version: "1.0.0" }); await client.connect(new StreamableHTTPClientTransport(new URL("https://host/mcp"))). For a local process use StdioClientTransport({ command, args }) from @modelcontextprotocol/client/stdio. For servers that predate Streamable HTTP, catch the failure and retry with SSEClientTransport on a fresh Client. After connect, getServerVersion(), getServerCapabilities(), and getInstructions() return what the server declared. Coming from v1, only the import paths moved. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/typescript-sdk/blob/main/docs/clients/connect.md', 'Apache-2.0', '8eccae7d55793ed3de30bf959b3c56d0a42c0fa109bfefacd653ef768fdb7eb1', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-python-v2-mcpserver', 'mcp-python', '2.3', 'MCP Python SDK v2: FastMCP is now MCPServer', 'In MCP Python SDK v2 the high-level server class is MCPServer: from mcp.server import MCPServer; mcp = MCPServer("Demo"). The v1 import from mcp.server.fastmcp import FastMCP is gone, not deprecated. @mcp.tool(), @mcp.resource(), and @mcp.prompt() still work, and input schemas still come from type hints. Modules under mcp.server.fastmcp.* moved to mcp.server.mcpserver.*, ctx.fastmcp became ctx.mcp_server, get_context() was removed (declare a ctx: Context parameter), and FastMCPError is now MCPServerError. pip install mcp installs 2.x. This is a short original summary for agents, not a substitute for the official API reference.', 'https://py.sdk.modelcontextprotocol.io/whats-new/', 'MIT', 'af129389788b46f88b901c8f412b65772ddc6e0df5bea6f34a559e704e2be470', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-python-v2-quickstart', 'mcp-python', '2.3', 'Write and run a minimal MCP server in Python', 'Install with uv add "mcp[cli]" or pip install "mcp[cli]" (Python 3.11+); the cli extra adds the mcp command. Define tools as typed functions: @mcp.tool() def add(a: int, b: int) -> int: """Add two numbers.""" return a + b. Type hints become the JSON Schema and the docstring becomes the description. @mcp.resource("greeting://{name}") defines a templated resource. Run uv run mcp dev server.py to open the MCP Inspector, or uv run mcp run server.py --transport streamable-http to serve over HTTP. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/python-sdk', 'MIT', '966610ddaa47bf191a23b243eb78f1529ba9af25701df53ce4a2773ca9044094', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('mcp-python-v2-client', 'mcp-python', '2.3', 'Call an MCP server from Python with mcp.Client', 'MCP Python SDK v2 has a first-class client: from mcp import Client; async with Client("http://localhost:8000/mcp") as client: result = await client.call_tool("add", {"a": 1, "b": 2}). Then result.structured_content holds {"result": 3}. A URL means Streamable HTTP. Client can also launch a local server as a stdio subprocess or take a custom transport. v2 speaks the 2026-07-28 protocol revision, which removes the connection handshake and sessions, while staying compatible with existing clients. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/modelcontextprotocol/python-sdk', 'MIT', '53b86363549521bbcd6b743228c7d0ee52b7c2ea721820402d1b204aea84abba', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('phantom-react-sdk-provider', 'phantom-connect', '2.0', 'Set up PhantomProvider in the Phantom Connect React SDK', 'Install @phantom/react-sdk plus @solana/web3.js or @solana/kit for Solana (viem for EVM). Wrap the app in <PhantomProvider config={{ providers: ["google", "apple", "injected"], appId, addressTypes: [AddressType.solana], authOptions: { redirectUrl } }} theme={darkTheme} appName="...">. AddressType comes from @phantom/browser-sdk. Use useModal() for open/close and usePhantom() for isConnected and user. google and apple are embedded providers that need a Phantom Portal appId and an allowlisted redirectUrl; injected (the extension) needs neither. Phantom Portal is currently not accepting new applications, though existing App IDs keep working. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.phantom.com/sdks/react-sdk', 'proprietary', '577ee84e1d8772d7de1861c2933d0dfa4838b42f16da7bc71df5f7763c06591a', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('phantom-browser-sdk-connect', 'phantom-connect', '2.0', 'Connect a wallet with the Phantom Browser SDK', 'With @phantom/browser-sdk: const sdk = new BrowserSDK({ providers: ["google", "apple", "injected"], addressTypes: [AddressType.solana], appId }); const { addresses } = await sdk.connect({ provider: "google" }). The provider passed to connect must be in the providers list. Call await sdk.isPhantomInstalled() before choosing injected, and fall back to an embedded provider if it returns false. After connecting, sdk.solana.signMessage, signTransaction, signAndSendTransaction, switchNetwork("devnet"), and publicKey are available. autoConnect defaults to true when embedded providers are used. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.phantom.com/sdks/browser-sdk/connect', 'proprietary', '07bc8d76bdc8d5f178b2566516cb6332214a0cea2566b634e96443ccf6cf52d2', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('phantom-react-sign-and-send', 'phantom-connect', '2.0', 'Phantom embedded wallets support only signAndSendTransaction', 'In the Phantom Connect React SDK, const { solana } = useSolana(); const result = await solana.signAndSendTransaction(transaction) returns result.signature. signTransaction and signAllTransactions are not supported for embedded (Google/Apple) wallets, which accept only signAndSendTransaction, and their transactions pass Phantom''s simulation checks first. Embedded wallets reject pre-signed transactions. For dapp fee-payer flows, pass a presignTransaction callback that calls your backend for the co-signature, and never keep the fee-payer keypair in frontend code. This is a short original summary for agents, not a substitute for the official API reference.', 'https://docs.phantom.com/sdks/react-sdk/sign-and-send-transaction', 'proprietary', '4b9f558872693034c45607a6280db001750d346d1fe09a2b0df47acbc501195b', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ai-sdk-generate-text', 'ai-sdk', '7.0', 'Generate text with the AI SDK and a provider/model string', 'Install ai (Node.js 22+). const { text } = await generateText({ model: "openai/<model-id>", prompt: "What is an agent?" }). A plain "provider/model" string routes through the Vercel AI Gateway by default. To call a provider directly, install its package (for example @ai-sdk/openai, @ai-sdk/anthropic, @ai-sdk/google) and pass model: anthropic("<model-id>") instead. The same call shape works across providers. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/vercel/ai', 'Apache-2.0', 'c45629eb4a08f71609f0f4f7b831ab6663b835326607687c4d14a42934c407c6', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ai-sdk-structured-output', 'ai-sdk', '7.0', 'Get structured output from generateText with Output.object', 'In the AI SDK, structured data comes from generateText with an output spec: const { output } = await generateText({ model, output: Output.object({ schema: z.object({ recipe: z.object({ name: z.string(), steps: z.array(z.string()) }) }) }), prompt: "Generate a lasagna recipe." }). Import generateText and Output from "ai" and z from "zod". The typed result is on output, not text. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/vercel/ai', 'Apache-2.0', '3b425666145f4c31e5fb207cc238c25abdb5c4df728063d3e8b4b88e05ec66dd', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('ai-sdk-tool-loop-agent', 'ai-sdk', '7.0', 'Build an agent with ToolLoopAgent in the AI SDK', 'new ToolLoopAgent({ model, system, tools: { ... } }) from "ai" defines an agent that calls tools in a loop. In a Next.js route, return createAgentUIStreamResponse({ agent, messages }) to stream to the UI, and type UI messages with InferAgentUIMessage<typeof agent>. On the client, useChat() from @ai-sdk/react gives messages, status, and sendMessage({ text }). Tool parts render by invocation.state, such as input-available and output-available. This is a short original summary for agents, not a substitute for the official API reference.', 'https://github.com/vercel/ai', 'Apache-2.0', '92529c5b551563ef16e0f00e6ddd3e0af25c492c5c551fe53e04281b71e0c944', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('hono-cloudflare-workers', 'hono', '4.13', 'Run Hono on Cloudflare Workers', 'Scaffold with npm create hono@latest my-app and pick the cloudflare-workers template. A minimal app: import { Hono } from "hono"; const app = new Hono(); app.get("/", (c) => c.text("Hello Cloudflare Workers!")); export default app. npm run dev serves on http://localhost:8787 and npm run deploy publishes with Wrangler. To add other handlers such as scheduled, export { fetch: app.fetch, scheduled: async (batch, env) => {} }. Serve static files with the Workers Static Assets setting "assets": { "directory": "public" } in wrangler.jsonc. This is a short original summary for agents, not a substitute for the official API reference.', 'https://hono.dev/docs/getting-started/cloudflare-workers', 'MIT', '500fe29735db2a47da44f48c1a6b701419c2ee828c262fcd6ed7350e3d819a7a', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('hono-routing-params', 'hono', '4.13', 'Hono routing: methods, path params, optional and regex params', 'Hono routes per method (app.get, post, put, delete), app.all for any method, and app.on("PURGE", "/cache", h) or app.on(["PUT", "DELETE"], "/post", h) for custom or multiple methods. Read one path param with c.req.param("name") or all with c.req.param(). Optional params use /api/animal/:type?, and regex constraints use /post/:date{[0-9]+}/:title{[a-z]+}. Group routes in a sub-app (const book = new Hono()) and mount it with app.route("/book", book). This is a short original summary for agents, not a substitute for the official API reference.', 'https://hono.dev/docs/api/routing', 'MIT', '0a6a9be68a0769830b8ce6de50cf86b7414ed4a97237bf9cd9df6ee5399b6aa3', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('hono-validator', 'hono', '4.13', 'Validate requests in Hono with validator() and c.req.valid()', 'import { validator } from "hono/validator" and use it as middleware: validator("form", (value, c) => { if (!value.body) return c.text("Invalid!", 400); return { body: value.body } }). The handler reads the result with c.req.valid("form"). Targets are json, form, query, header, param, and cookie. For json and form the request needs a matching Content-Type header or the value is {}, which also matters in app.request() tests. Header keys must be lowercase, such as idempotency-key. This is a short original summary for agents, not a substitute for the official API reference.', 'https://hono.dev/docs/guides/validation', 'MIT', '8511af193addc2569827d77b8f14a90cea2c0bf58af15ce0418996c4bdb7aff7', 'house', 1, 'verified', '2026-11-20T00:00:00.000Z', '2026-11-20');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('supabase-create-client', 'supabase', '2.119', 'createClient takes your project URL and a publishable key', 'Install @supabase/supabase-js and call createClient(supabaseUrl, supabaseKey). The first argument is your project URL (https://<project>.supabase.co). The second is the project''s publishable key (not the service role key, which must stay on a server). The same helper works in browsers, Node.js, and Deno (import from npm:@supabase/supabase-js@2). Pass an optional third argument for client options such as auth storage. supabase-js talks to your database through the Data API, so tables must be exposed and granted to the anon or authenticated roles after RLS is in place. This is a short original summary for agents, not a substitute for the official documentation.', 'https://supabase.com/docs/reference/javascript/initializing', 'Apache-2.0', '750daf0df5143b9f02426851a6926ccefb7770e19f6606e9428e64e0538b3560', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('supabase-select', 'supabase', '2.119', 'from().select() queries a table through the Data API', 'const { data, error } = await supabase.from(''profiles'').select(''*'') runs a query against a Postgres table exposed by the Data API. Chain filters and modifiers on the builder (for example .eq(''id'', id), .order(), .limit()). Select specific columns with a comma-separated list, and request related rows with embedded resource syntax when foreign keys exist. Always check error; a successful call returns typed rows when you generate TypeScript types from your schema. Nullable columns are typed as T | null. This is a short original summary for agents, not a substitute for the official documentation.', 'https://supabase.com/docs/reference/javascript/select', 'Apache-2.0', '62099a40bae317abbeec30efc44da570122f9e71b61904eea078a7e60cc4c192', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('supabase-signin-password', 'supabase', '2.119', 'signInWithPassword authenticates with email or phone plus a password', 'const { data, error } = await supabase.auth.signInWithPassword({ email, password }) logs in an existing user. You can pass phone instead of email. The returned error does not tell you whether the account is missing, the password is wrong, or the user must use social sign-in — treat it as a generic failure. On success, data includes a session (access token, refresh token, and user). Supabase Auth also supports magic links, OTP, OAuth, SSO, and passkeys. JWTs from Auth are what Row Level Security policies evaluate. This is a short original summary for agents, not a substitute for the official documentation.', 'https://supabase.com/docs/reference/javascript/auth-signinwithpassword', 'Apache-2.0', 'eee2371934e92e68e749c156d560e2f531ec60b9d6c3f04188df2ff1c14c8e3a', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('supabase-rls', 'supabase', '2.119', 'Enable Row Level Security before granting table access to client roles', 'Supabase Auth issues JWTs; authorization for table data is done with Postgres Row Level Security. Enable RLS on the table and create policies for each allowed operation before you GRANT anything to client roles. Official guidance is: ALTER TABLE ... ENABLE ROW LEVEL SECURITY, add policies, then GRANT select to anon and GRANT select, insert, update, delete to authenticated as needed. The service_role key bypasses RLS and must never be shipped to a browser. New tables should not be left world-readable by default. This is a short original summary for agents, not a substitute for the official documentation.', 'https://supabase.com/docs/guides/database/postgres/row-level-security', 'Apache-2.0', '50ead0d128834447305af63f7dc680b7b20f17d69757a4466abc0f7576fbe8d0', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('supabase-realtime-channel', 'supabase', '2.119', 'channel() subscribes to broadcast, presence, or database changes', 'const channel = supabase.channel(''room1'') creates a Realtime channel. Listen with channel.on(''broadcast'', { event }, handler), channel.on(''presence'', { event: ''sync'' | ''join'' | ''leave'' }, handler), or a postgres_changes listener, then call .subscribe(). After the status is SUBSCRIBED you can channel.send({ type: ''broadcast'', event, payload }) or channel.track(state) for presence. Realtime can also stream database changes; with RLS enabled, replica identity and policies determine what clients receive. This is a short original summary for agents, not a substitute for the official documentation.', 'https://supabase.com/docs/guides/realtime', 'Apache-2.0', 'a60398c3e9d6c7d2809313e2636bbf7057e40eab144418f7030d4f166de82fea', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('drizzle-pg-connect', 'drizzle', '0.45', 'drizzle() connects to PostgreSQL with a URL or a node-postgres pool', 'Install drizzle-orm and the pg driver. import { drizzle } from ''drizzle-orm/node-postgres'' and create a client with const db = drizzle(process.env.DATABASE_URL) or drizzle({ client: pool }) after constructing a pg.Pool. The same package also ships drivers for postgres.js, Neon, Supabase, D1, and other backends — import from the matching drizzle-orm/<driver> path. Keep DATABASE_URL in the environment; do not hard-code credentials. This is a short original summary for agents, not a substitute for the official documentation.', 'https://orm.drizzle.team/docs/get-started/postgresql-new', 'Apache-2.0', '878537834812119db8d99629028553ac49188a47d0400dacb0ed844811c1ca3a', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('drizzle-pg-table', 'drizzle', '0.45', 'pgTable declares a typed PostgreSQL schema in TypeScript', 'import { integer, pgTable, varchar } from ''drizzle-orm/pg-core'' and export const usersTable = pgTable(''users'', { id: integer().primaryKey().generatedAlwaysAsIdentity(), name: varchar({ length: 255 }).notNull(), email: varchar({ length: 255 }).notNull().unique() }). The object keys become the TypeScript field names; column types come from the pg-core helpers. Use $inferInsert and $inferSelect on the table for insert and select types. Put this in a schema.ts file and point Drizzle Kit at it. This is a short original summary for agents, not a substitute for the official documentation.', 'https://orm.drizzle.team/docs/get-started/postgresql-new', 'Apache-2.0', '42fd70261768be644038097d313b3b8e6b0a73e502e9496946b264c916003b1b', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('drizzle-crud', 'drizzle', '0.45', 'insert, select, update, and delete are chained on the db object', 'await db.insert(usersTable).values(user) inserts a row. await db.select().from(usersTable) returns a typed array. Updates and deletes take a table and a WHERE clause: db.update(usersTable).set({ age: 31 }).where(eq(usersTable.email, email)) and db.delete(usersTable).where(eq(usersTable.email, email)). Import eq and other helpers from drizzle-orm. Queries are composable SQL builders, not string concatenation. This is a short original summary for agents, not a substitute for the official documentation.', 'https://orm.drizzle.team/docs/get-started/postgresql-new', 'Apache-2.0', 'ef8269ef8c3762c9ab036db01dd0fe1c1fd2e73ff50c80cf05f61c7cff462f6b', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('drizzle-kit-config', 'drizzle', '0.45', 'drizzle.config.ts tells Drizzle Kit the schema, dialect, and credentials', 'Create drizzle.config.ts at the project root: import { defineConfig } from ''drizzle-kit'' and export default defineConfig({ out: ''./drizzle'', schema: ''./src/db/schema.ts'', dialect: ''postgresql'', dbCredentials: { url: process.env.DATABASE_URL } }). out is where SQL migrations and snapshots are written. schema can be a file or glob. dialect must match your database (postgresql, mysql, sqlite, and others). This is a short original summary for agents, not a substitute for the official documentation.', 'https://orm.drizzle.team/docs/drizzle-config-file', 'Apache-2.0', '0c28e7a3651295811f10ce4eef26ade60d085681cf0b40c247c434dda6af8a62', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('drizzle-kit-migrate', 'drizzle', '0.45', 'drizzle-kit push applies schema quickly; generate and migrate write SQL files', 'npx drizzle-kit push pushes the current TypeScript schema to the database without writing migration files — convenient for local iteration. For a durable history, run npx drizzle-kit generate to emit SQL under the configured out folder, then npx drizzle-kit migrate to apply those files. Install drizzle-kit as a dev dependency. Do not use push as your only workflow in production if you need reviewable, versioned migrations. This is a short original summary for agents, not a substitute for the official documentation.', 'https://orm.drizzle.team/docs/get-started/postgresql-new', 'Apache-2.0', '5b542fe9f3e8c0cf6a52b393f8ffa8181019bf4e0907482b020e95fd8911a6ac', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('trpc-init-router', 'trpc', '11.29', 'initTRPC creates the router and procedure builder', 'Install @trpc/server and @trpc/client. tRPC requires TypeScript 5.7.2 or later, and official support assumes "strict": true in tsconfig.json. const t = initTRPC.create() (or initTRPC.context<Context>().create() when you have context) yields t.router and t.procedure. Export router and a renamed publicProcedure = t.procedure, then compose an appRouter = router({ ... }) and export type AppRouter = typeof appRouter so the client can import only the type. This is a short original summary for agents, not a substitute for the official documentation.', 'https://trpc.io/docs/quickstart', 'MIT', 'f8be05760dda51fe46207087cc4015e013b1c06b4850b4c1d3d2a58935f72914', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('trpc-procedures', 'trpc', '11.29', 'Procedures are query, mutation, or subscription builders', 'A procedure is a backend function exposed to the client: a query fetches data and generally does not change it; a mutation creates, updates, or deletes; a subscription is a separate, less commonly needed path. Build on publicProcedure.query(() => { ... }) or .mutation(async (opts) => { ... }). The builder is immutable, so you can chain .input(), .use(), and other helpers and reuse the result as a base procedure. Access context as opts.ctx inside the resolver. This is a short original summary for agents, not a substitute for the official documentation.', 'https://trpc.io/docs/server/procedures', 'MIT', 'd9e2731079bebe8a6d0a7f28a4fa785215bc5971b10b27a6c391425d2077fa00', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('trpc-base-procedures', 'trpc', '11.29', 'Base procedures share auth and validation with .use() middleware', 'Rename t.procedure to publicProcedure and build specialized procedures from it. For example authedProcedure = t.procedure.use(async function isAuthed(opts) { if (!opts.ctx.user) throw new TRPCError({ code: ''UNAUTHORIZED'' }); return opts.next({ ctx: { user: opts.ctx.user } }) }). Later procedures see a narrowed context. You can chain further, such as an organizationProcedure that reads input.organizationId and throws FORBIDDEN when the user is not a member. This is the recommended reuse pattern in tRPC. This is a short original summary for agents, not a substitute for the official documentation.', 'https://trpc.io/docs/server/procedures', 'MIT', 'd50a719a2129c033b99a3c62a7db4b2bf364f688e15a4f96d29e0934625e8fbb', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('trpc-input-zod', 'trpc', '11.29', 'procedure.input() validates inputs with a schema such as Zod', 'Chain .input(z.object({ id: z.string() })) (or another Standard Schema library) before .query or .mutation. Invalid input is rejected before the resolver runs. The resolver then receives a typed opts.input. Reusable base procedures can also declare shared input (for example organizationId) so every procedure built from them requires it. Keep input schemas at the procedure boundary rather than parsing inside the handler. This is a short original summary for agents, not a substitute for the official documentation.', 'https://trpc.io/docs/server/procedures', 'MIT', 'd80367e3b78b74a9114f4adfe741bfcc293116e9f3e7840f793f31d1da8055e3', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('trpc-client-setup', 'trpc', '11.29', 'createTRPCClient infers types from the AppRouter type only', 'On the client, install @trpc/client and import type { AppRouter } from your server (type-only). createTRPCClient<AppRouter>({ links: [httpBatchLink({ url: ''http://localhost:3000/trpc'' })] }) gives a typed client: await client.hello.query() or client.userCreate.mutate({ name }). There is no generated runtime code; TypeScript inference is the contract. Framework adapters (TanStack React Query, Next.js) wrap this client rather than replacing it. This is a short original summary for agents, not a substitute for the official documentation.', 'https://trpc.io/docs/quickstart', 'MIT', '50921da1195bb8abeb49188acfcb4d3725466c7d01182fdcce60b21f7697d220', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anthropic-messages-api', 'anthropic', '1.12', 'POST /v1/messages is the Claude Messages API', 'Send conversational requests to https://api.anthropic.com/v1/messages. Required JSON fields include model, max_tokens, and messages (an array of { role, content } turns; roles are user and assistant). Required headers include content-type: application/json and anthropic-version (for example 2026-10-21). Authenticate with x-api-key or Authorization: Bearer <token>. Official SDKs set the version and auth headers for you. The API is stateless: send prior turns in messages when you need a multi-turn conversation. This is a short original summary for agents, not a substitute for the official API reference.', 'https://platform.claude.com/docs/en/api/overview', 'proprietary', 'bd5024826e4d8921494268c1f75e1aee3513eab2a0d3a3cef8646d07d5ae86af', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anthropic-models', 'anthropic', '1.12', 'Current Claude model IDs include Opus 5.5, Sonnet 5.5, and Haiku 5.5', 'Official docs recommend Claude Opus 5.5 (claude-opus-5-5) as the default for most work, including complex agentic coding. Claude Fable 5.2 (claude-fable-5-2) is positioned for the hardest long-running agentic and research tasks. Claude Sonnet 5.5 (claude-sonnet-5-5) is the smart mid-tier model, and Claude Haiku 5.5 (claude-haiku-5-5) is for fast, cost-effective tasks. Use these IDs in the model field of a Messages request. Check the models overview for newer aliases before hard-coding a snapshot. This is a short original summary for agents, not a substitute for the official API reference.', 'https://platform.claude.com/docs/en/claude_api_primer', 'proprietary', '2c5dd99882b81514af3e699e93b47d4f407748f20f08b89a40278f3d7047f30f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anthropic-sdk-messages-create', 'anthropic', '1.12', 'The official SDKs call messages.create on a client', 'In Python, pip install anthropic, set ANTHROPIC_API_KEY, then message = anthropic.Anthropic().messages.create(model=''claude-opus-5-5'', max_tokens=1024, messages=[{''role'': ''user'', ''content'': ''Hello, Claude''}]). The TypeScript SDK (@anthropic-ai/sdk) follows the same shape on a client.messages.create(...) call. The response is a message with a content array of blocks (type text for plain replies). max_tokens is required; it caps the output, it is not optional. This is a short original summary for agents, not a substitute for the official API reference.', 'https://platform.claude.com/docs/en/get-started', 'proprietary', '5c17b67a79e2edb8aa1f72ac3dd7d2cc2723f81436bcf49a917b04150edad234', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anthropic-thinking', 'anthropic', '1.12', 'Adaptive thinking is the current thinking mechanism on current models', 'Thinking can help with very hard tasks. The current mechanism is adaptive thinking: thinking: { type: ''adaptive'' }. Claude decides when and how much to think; you steer depth with the effort parameter rather than a token budget. Official docs say adaptive thinking is supported on Claude 4.6 and later (and Claude Mythos Preview), and that on Claude 5 and later, thinking is on by default when the thinking parameter is omitted. Model-specific exceptions exist (for example some models are always on, and some reject thinking: { type: ''disabled'' }). This is a short original summary for agents, not a substitute for the official API reference.', 'https://platform.claude.com/docs/en/claude_api_primer', 'proprietary', 'fab19e20778b670fdd4271de60344fb529e548e0bc86c20a84e913d0d77e15f2', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anchor-cli-workflow', 'anchor', '1.2', 'anchor init, build, test, and deploy are the core CLI workflow', 'Official docs install Anchor CLI 1.2.x (verify with anchor --version). Create a workspace with anchor init my-project (optionally --test-template mollusk, rust, mocha, or jest; the default test template is LiteSVM/Rust). cd into the project, then anchor build writes a .so under target/deploy. anchor test on localnet starts a local validator, deploys, runs tests, and stops the validator. anchor deploy uses the cluster in Anchor.toml. After cloning a repo, run anchor keys sync so declare_id! matches the local program keypair. This is a short original summary for agents, not a substitute for the official documentation.', 'https://www.anchor-lang.com/docs/quickstart/local', 'Apache-2.0', '01ba99e8729cceda1395822138cb788abe9ef7e3b63b45d3ea8dd7a54f312b1f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anchor-program-macros', 'anchor', '1.2', 'declare_id, #[program], #[derive(Accounts)], and #[account] structure a program', 'use anchor_lang::prelude::*; then declare_id!("...") for the program address. #[program] marks the module whose public functions are instruction handlers; each handler takes Context<T> as its first argument. #[derive(Accounts)] on a struct lists the accounts an instruction must receive. #[account] on a data struct defines a program-owned account type (Anchor sets the owner, writes an 8-byte discriminator, and (de)serializes the data). New workspaces also split instructions, state, constants, and errors into modules. This is a short original summary for agents, not a substitute for the official documentation.', 'https://www.anchor-lang.com/docs/basics/program-structure', 'Apache-2.0', 'd873341d19c15dec3cc5e67c8836d98752bbe0210b986a4f1774ef44561a1efd', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anchor-account-constraints', 'anchor', '1.2', '#[account(...)] constraints and account types validate instruction accounts', 'Inside a #[derive(Accounts)] struct, put constraints on each field. #[account(init, payer = signer, space = 8 + 8)] creates a new account, charging signer, and reserves 8 bytes for Anchor''s discriminator plus your data (here a u64). #[account(mut)] marks an account writable. Common types include Account<''info, T>, Signer<''info>, and Program<''info, System>. Anchor validates accounts before the handler runs; in the handler you use ctx.accounts, ctx.program_id, and ctx.bumps. This is a short original summary for agents, not a substitute for the official documentation.', 'https://www.anchor-lang.com/docs/basics/program-structure', 'Apache-2.0', 'b4e5cda35c4fefb5fd5dfd2b3c6515391272b239c03209d55b295c0c025d7d2f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anchor-toml-cluster', 'anchor', '1.2', 'Anchor.toml [provider] cluster selects localnet, devnet, or mainnet', 'The [provider] table in Anchor.toml sets cluster and wallet (default wallet is ~/.config/solana/id.json). Default projects use Localnet so anchor test can boot solana-test-validator for you. Change cluster to Devnet or Mainnet before anchor deploy or anchor test against that cluster. [programs.localnet] (and the corresponding cluster tables) record program IDs. Deploying to devnet or mainnet requires SOL in the configured wallet for the program account and fees. To keep a local validator running yourself, start solana-test-validator and pass anchor test --skip-local-validator. This is a short original summary for agents, not a substitute for the official documentation.', 'https://www.anchor-lang.com/docs/quickstart/local', 'Apache-2.0', '377b78e049816a9413b37913a6ce0c1328c729cfd062fb68eb584300a48a1986', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('anchor-install-avm', 'anchor', '1.2', 'Install the Solana toolchain, then the Anchor CLI via AVM', 'Official docs start with the Solana install script (curl --proto ''=https'' --tlsv1.2 -sSfL https://solana-install.solana.workers.dev | bash) on macOS and Linux (Windows uses WSL first), or install Rust, the Solana CLI, and Anchor separately. The recommended way to manage Anchor versions is AVM: avm install latest && avm use latest, or avm install 1.2.2 && avm use 1.2.2. Then confirm with anchor --version. Node.js and Yarn are needed when you initialize a project or use a TypeScript test template; the default LiteSVM tests do not require them day to day. This is a short original summary for agents, not a substitute for the official documentation.', 'https://www.anchor-lang.com/docs/installation', 'Apache-2.0', '7161525fd32632e34517a62a5f68e562910994f30f34bafad7018937f8050ce2', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('cf-workers-fetch-handler', 'cloudflare-workers', 'docs-2026-11', 'The fetch() handler receives Request and must return a Response', 'Incoming HTTP requests are passed to the module Worker''s fetch() handler. The documented form is: export default { async fetch(request, env, ctx) { return new Response(''Hello World!''); } }. request is the standard Request, env holds bindings, and ctx provides waitUntil() and passThroughOnException(). Return a Response (or a promise of one). The Workers runtime does not support XMLHttpRequest; use fetch() for outbound HTTP. This is a short original summary for agents, not a substitute for the official documentation.', 'https://developers.cloudflare.com/workers/runtime-apis/handlers/fetch/', 'CC-BY-SA-4.0', 'e7577042ad59a2f3c9e9afea1e90aad587ce8eb76183e0605fd9eef68cb55264', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('cf-workers-c3', 'cloudflare-workers', 'docs-2026-11', 'Create a Worker with npm create cloudflare@latest, then deploy with Wrangler', 'Official CLI getting-started uses C3: npm create cloudflare@latest -- my-first-worker (or yarn/pnpm create cloudflare). The wizard can scaffold a Hello World Worker-only project and write wrangler.jsonc. cd into the project to iterate, then deploy with Wrangler (npx wrangler deploy) once you are ready. You need a Cloudflare account and a supported Node.js version for Wrangler. C3 can also add an AGENTS.md file for coding agents. This is a short original summary for agents, not a substitute for the official documentation.', 'https://developers.cloudflare.com/workers/get-started/guide/', 'CC-BY-SA-4.0', 'dc88b7125b3aa6f1569bea532547d43dac6e48ed145a155f515d4d8eccb0ba52', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('cf-workers-bindings-env', 'cloudflare-workers', 'docs-2026-11', 'Bindings are available on the env argument of fetch()', 'Bindings connect a Worker to other Developer Platform resources (KV, D1, R2, Durable Objects, secrets, and more) without putting credentials in your source. They appear as properties on the env object passed to fetch(request, env, ctx). You can also import env from ''cloudflare:workers'' to read bindings outside the handler. Declare bindings in wrangler.jsonc (or wrangler.toml). As long as the environment has not changed, the same env object may be reused across requests. This is a short original summary for agents, not a substitute for the official documentation.', 'https://developers.cloudflare.com/workers/runtime-apis/bindings/', 'CC-BY-SA-4.0', '43185c6cd4ea22c41dc0ac6e07e697784967f86866b8304313d29489931ac59e', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('cf-workers-wrangler-config', 'cloudflare-workers', 'docs-2026-11', 'wrangler.jsonc configures name, entry, compatibility_date, and bindings', 'Wrangler reads wrangler.jsonc (or wrangler.toml) for the Worker name, main entry file, compatibility_date, and resource bindings. compatibility_date selects which runtime APIs are available; update it deliberately when you want newer behavior. C3 writes a starter config including source-map upload settings for JS/TS projects. Environments let you vary bindings and routes per dev/staging/production rather than hard-coding them in the handler. This is a short original summary for agents, not a substitute for the official documentation.', 'https://developers.cloudflare.com/workers/wrangler/configuration/', 'CC-BY-SA-4.0', '5590f487da8c11313a9fec933445198da7e87e974d5d9169342d087533ed3860', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('cf-workers-module-format', 'cloudflare-workers', 'docs-2026-11', 'ES module syntax is the supported Worker format', 'Write Workers as ES modules: a default export with fetch (and optional scheduled, queue, or other handlers) rather than the legacy addEventListener(''fetch'', ...) service-worker syntax. Official docs recommend migrating any remaining service-worker Workers to modules. Module Workers get a clearer env and ctx, better tree-shaking, and current tooling support. TypeScript projects typically use a generated Env interface so bindings are typed. This is a short original summary for agents, not a substitute for the official documentation.', 'https://developers.cloudflare.com/workers/reference/migrate-to-module-workers/', 'CC-BY-SA-4.0', '376b956a55b9704d6a82bdbbf2b8d396551624c8eb9cf4d1752e13be309e4279', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('expo-create-app', 'expo', '58.0', 'npx create-expo-app@latest scaffolds an Expo project with Expo Router', 'Official docs recommend npx create-expo-app@latest (or yarn create expo-app, pnpm create expo-app, bun create expo) to start a universal app with Expo Router already configured. Then npx expo start (or the yarn/pnpm/bun equivalent) launches the dev server. In the terminal UI, press W for web, A for Android, or I for iOS (Xcode on macOS is required for the iOS simulator). Start on a physical device with Expo Go; move to a development build when you need custom native code. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.expo.dev/router/introduction/', 'MIT', '01e9f768f13afe32b94d8019c0e6490f4a70854d91eb9c90d8c3d5dc509cbc0d', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('expo-router-routes', 'expo', '58.0', 'Expo Router maps files in the app directory to routes', 'Expo Router is a file-based router for Android, iOS, and web. When you add a file to the app directory, it becomes a route, so the same components can navigate on every platform. create-expo-app sets this up for you; you can also install the router manually if you are adding it to an existing project. URLs and screen names follow the file tree, similar to other file-system routers on the web. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.expo.dev/router/introduction/', 'MIT', 'f8c30ebc8e105614e88d62f6c2c6d58847dad4341d87ae453e7451dedaab442b', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('expo-development-builds', 'expo', '58.0', 'Development builds replace Expo Go once you need custom native code', 'Expo Go is the fastest way to preview an app on a device, but it only includes a fixed set of native modules. A development build is your own debug binary (with your native dependencies) that still loads the JS bundle from the dev server. Create one when you add custom native code, a config plugin that changes native projects, or a library that is not in Expo Go. You can produce development builds locally or with EAS Build. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.expo.dev/develop/development-builds/introduction/', 'MIT', '4773ceea3d13bdb8c3df91321b3413a8af0bf0dec2e3e37007ad28e1aa269773', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('expo-app-config', 'expo', '58.0', 'app.json, app.config.js, or app.config.ts is the Expo app config', 'The Expo app config lives at app.json, or at app.config.js / app.config.ts when you need a dynamic config. It sets the app name, slug, icons, splash, scheme, platform settings, and the plugins/config plugins that change native projects during prebuild. Keep secrets out of this file if it is committed; use environment variables or EAS secrets for sensitive values. The official configuration guide covers static versus dynamic config and how values are applied. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.expo.dev/workflow/configuration/', 'MIT', '3dae635725b7cb2e64c0487d7960879af5c0352572c76e8ffcad9e35b3b8bfd8', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('expo-eas-build', 'expo', '58.0', 'EAS CLI and eas.json configure Expo Build for Android and iOS', 'Cloud native builds use Expo Build via EAS CLI: install with npm install -g eas-cli, log in with eas login (or set EXPO_TOKEN; never print a token). If the project has no eas.json, run eas build:configure --platform <android|ios> in a real terminal because it asks questions. Then create a development build for devices/simulators or a production build for the stores, following the platform and profile in eas.json. Local credentials and store submission are separate, later steps. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.expo.dev/build/setup/', 'MIT', '8ee6033066cd0bed76ea5a8fc87328ffbd77f5fab1236a0ae4c88fb543eaf7dc', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('tanstack-query-provider', 'tanstack-query', '5.108', 'QueryClientProvider makes a QueryClient available to hooks', 'Install @tanstack/react-query. Create const queryClient = new QueryClient() once and wrap the tree with <QueryClientProvider client={queryClient}>. Hooks such as useQuery and useMutation only work under that provider. Keep a single client per app (or per logical session); creating a new QueryClient on every render would reset the cache. This is a short original summary for agents, not a substitute for the official documentation.', 'https://tanstack.com/query/latest/docs/framework/react/overview', 'MIT', '20e45ccc6b54d2034947122d6509e5c04d86b9c44bed0c26ac37014f104b88bf', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('tanstack-query-usequery', 'tanstack-query', '5.108', 'useQuery needs a queryKey and a queryFn', 'const { isPending, error, data } = useQuery({ queryKey: [''repoData''], queryFn: async () => { const response = await fetch(url); if (!response.ok) throw new Error(''Failed to fetch''); return response.json() } }) is the documented basic form. queryKey identifies the cache entry; queryFn returns a promise of data or throws. In v5 the pending state is isPending (not the older isLoading-first examples). Render a loading state when isPending, an error message when error is set, and data only after a successful fetch. This is a short original summary for agents, not a substitute for the official documentation.', 'https://tanstack.com/query/latest/docs/framework/react/overview', 'MIT', 'd5b2041e3c46ecf5ba76d9f1d74a7682bc9aefd94505c2f0f7c54b0bb45902c2', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('tanstack-query-keys', 'tanstack-query', '5.108', 'Query keys uniquely identify cached queries and should be structured', 'Every query is cached under its queryKey. Official guidance is to use an array key, often with a scope string first and then the variables that change the result ([''todos'', { status, page }]). When a key changes, React Query treats it as a different query. Matching keys is also how you invalidate or prefetch: invalidate queries that start with [''todos''] after a mutation. Keep keys serializable and include every input the queryFn depends on. This is a short original summary for agents, not a substitute for the official documentation.', 'https://tanstack.com/query/latest/docs/framework/react/guides/query-keys', 'MIT', '36aedf0c67b2ed4bab13f5f49cc3de92ef50c99dd15fb059f3904962568c4bd5', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('tanstack-query-mutations', 'tanstack-query', '5.108', 'useMutation runs writes and can invalidate related queries', 'useMutation({ mutationFn, onSuccess }) is the hook for creates, updates, and deletes. Call mutate(variables) or mutateAsync(variables). Unlike useQuery, mutations are not automatically retried in the same way and are not cached as a query. In onSuccess (or the mutation cache callbacks) call queryClient.invalidateQueries({ queryKey: [''todos''] }) so lists refetch. The hook exposes isPending, error, and data for UI state. This is a short original summary for agents, not a substitute for the official documentation.', 'https://tanstack.com/query/latest/docs/framework/react/guides/mutations', 'MIT', '6e1327871e4167ff33e164c8c6e18c2ce6a8fe8c0868858d6dfac29d0c7e4b76', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('playwright-install', 'playwright', '1.65', 'npm init playwright@latest scaffolds Playwright Test and browsers', 'Install with npm init playwright@latest (or yarn create playwright / pnpm create playwright). The wizard picks TypeScript or JavaScript, a tests folder, an optional GitHub Actions workflow, and whether to install browser binaries. Run tests with npx playwright test (add --headed, --project=chromium, a file path, or --ui). Open the HTML report with npx playwright show-report. Update later with npm install -D @playwright/test@latest and npx playwright install --with-deps. Node.js latest 22.x, 24.x, or 26.x is required. This is a short original summary for agents, not a substitute for the official documentation.', 'https://playwright.dev/docs/intro', 'Apache-2.0', 'df54b69b0dad60981e67cc6e1eb78d7c1197a51e3b740d9ca1f37c0e07dde25f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('playwright-first-test', 'playwright', '1.65', 'Tests import test and expect from @playwright/test and use the page fixture', 'import { test, expect } from ''@playwright/test''; test(''has title'', async ({ page }) => { await page.goto(''https://playwright.dev/''); await expect(page).toHaveTitle(/Playwright/); }). The page fixture is an isolated browser page. Playwright waits for actionability before clicks and for assertions to pass, so you usually do not add manual sleeps. Tests in one file run with that same test() API; configure browsers and retries in playwright.config.ts. This is a short original summary for agents, not a substitute for the official documentation.', 'https://playwright.dev/docs/writing-tests', 'Apache-2.0', '2df7a62afac748d67b4b560e61279cc7ecc7dc5475e2e20a340f24bfb61279ed', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('playwright-locators', 'playwright', '1.65', 'getByRole and other locators auto-wait before actions', 'Locate elements with the Locators API, most often page.getByRole(''link'', { name: ''Get started'' }), then chain .click(), .fill(), .check(), .press(), or .selectOption(). Playwright waits until the element is actionable before performing the action, which removes many race conditions. Prefer role, label, and text locators over CSS or XPath when you can, because they follow how users and assistive tech see the page. This is a short original summary for agents, not a substitute for the official documentation.', 'https://playwright.dev/docs/writing-tests', 'Apache-2.0', 'b8f8c22e6a1c4d729e5978b16bed3dd03bbb77ba76539f71775437d056f52281', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('playwright-assertions', 'playwright', '1.65', 'Async expect matchers wait until the condition is true', 'Playwright assertions are designed to retry until they pass or time out. Use await expect(page).toHaveTitle(/Playwright/), await expect(locator).toBeVisible(), toContainText(), toHaveText(), toHaveURL(), toBeChecked(), and similar matchers. Generic matchers such as toEqual or toBeTruthy are synchronous and do not take await — use them only on values you already have. This auto-waiting is what makes tests less flaky than assert-immediately libraries. This is a short original summary for agents, not a substitute for the official documentation.', 'https://playwright.dev/docs/writing-tests', 'Apache-2.0', '1df65dca609e822c41e9c0f46ffba49f045f8a85767b52fafe6bc6e7ac92034d', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('playwright-isolation-hooks', 'playwright', '1.65', 'Each test gets an isolated BrowserContext; hooks wrap setup', 'The built-in page fixture belongs to a fresh Browser Context, equivalent to a new browser profile, so tests do not share cookies, storage, or pages even when they run in the same browser. Group tests with test.describe and use test.beforeEach / test.afterEach for per-test setup, or test.beforeAll / test.afterAll once per worker. A typical beforeEach is await page.goto(startUrl) so each test starts from a known page. This is a short original summary for agents, not a substitute for the official documentation.', 'https://playwright.dev/docs/writing-tests', 'Apache-2.0', 'b599b9f28de217a805e433623b6374a7394c6c79be502c0a195d4bdaa1d78ba5', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sveltekit-create', 'sveltekit', '3.4', 'npx sv create scaffolds a SvelteKit app in src/routes', 'The easiest way to start is npx sv create my-app, then cd my-app and npm run dev (install dependencies first if the scaffolder did not). The dev server defaults to http://localhost:5173. Each page is a Svelte component, and you add pages as files under src/routes. The first visit is server-rendered, then the client-side app takes over. The CLI can set up TypeScript and other tooling during create. This is a short original summary for agents, not a substitute for the official documentation.', 'https://svelte.dev/docs/kit/creating-a-project', 'MIT', 'a788027e71f93e7067a814f31eab5328e2b941dab8ece8b3c1bebcaf45bba999', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sveltekit-routing', 'sveltekit', '3.4', '+page, +layout, +error, and +server files define routes', 'Routes live in src/routes. +page.svelte is the page UI; +page.js or +page.server.js load data for that page. +layout.svelte (and +layout.js / +layout.server.js) wraps child routes. +error.svelte renders errors. +server.js (or .ts) defines HTTP handlers for that path. Folders name the URL segment; dynamic parameters use [param] folders. Colocate components used by only one route next to these files. $types is generated for each route''s typings. This is a short original summary for agents, not a substitute for the official documentation.', 'https://svelte.dev/docs/kit/routing', 'MIT', '8704e5d343c9abb9b780ddc7b32fc1d95e237e879c2c77f7182444a751976fc3', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sveltekit-load', 'sveltekit', '3.4', 'load functions in +page.js or +page.server.js provide page data', 'Export a load function from +page.js (universal) or +page.server.js (server-only) to supply data for a route. Server load can use secrets, cookies, and headers; universal load can also run in the browser. Return an object that becomes data in the page component. Use the provided fetch so requests are tracked correctly during SSR. Layout load functions contribute data to child pages. Redirect or throw errors from load when the user should not see the page. This is a short original summary for agents, not a substitute for the official documentation.', 'https://svelte.dev/docs/kit/load', 'MIT', '37f32b0617847329b57b254d6bcc44588b59c168afd89dfd6068b6a8b3372b5a', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sveltekit-form-actions', 'sveltekit', '3.4', 'Form actions in +page.server.js handle POST submissions', 'Export const actions from +page.server.js. The default action runs when a <form method=''POST''> on that page is submitted. Named actions (for example login and register) are invoked with action=''?/register'' or a button formaction=''?/register''. Actions always use POST because GET must not have side effects. You can post to another page''s action with action=''/login''. use:enhance progressively enhances the form so the page can stay put and apply the result without a full reload. This is a short original summary for agents, not a substitute for the official documentation.', 'https://svelte.dev/docs/kit/form-actions', 'MIT', '570978b4a96a9c980218b188ce51306eca110aeb7241bb2be55bb2d7e47f9c98', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('authjs-v5-beta', 'authjs', '5.0.0-beta', 'authjs.dev documents Auth.js / next-auth v5, which is still published as a beta', 'Auth.js is the documentation brand for next-auth@5.0.0-beta and later and for packages under the @auth/* namespace. Official getting-started docs state that they cover next-auth@5.0.0-beta and later; v4 docs remain at next-auth.js.org. On npm, the latest tag for next-auth may still be v4, so follow the Auth.js install instructions (including a beta tag when the docs say to use one) rather than assuming npm install next-auth installs v5. The library is runtime-agnostic and built on Web APIs. This is a short original summary for agents, not a substitute for the official documentation.', 'https://authjs.dev/getting-started', 'ISC', '206c88715ff1d875efc421d0d113206ae43dc4ffaeba86d18147ef054eeaaee6', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('authjs-secret', 'authjs', '5.0.0-beta', 'AUTH_SECRET is required; generate it with npx auth secret', 'The only mandatory environment variable is AUTH_SECRET, a random value used to encrypt tokens and email verification hashes. Generate and write it with the official CLI: npx auth secret, which also appends it to the framework''s env file (for example .env.local in Next.js). Do not commit the secret or put it in client-side code. You do not need to install @auth/core yourself; framework packages depend on it and official docs say users should not interact with it directly. This is a short original summary for agents, not a substitute for the official documentation.', 'https://authjs.dev/getting-started/installation', 'ISC', '9478b003aefe872b1c54a2886f7401f8a2062dce936d806da1b24715849a99d8', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('authjs-config-handlers', 'authjs', '5.0.0-beta', 'auth.ts exports handlers, signIn, signOut, and auth from NextAuth()', 'The recommended Next.js setup is a root auth.ts: import NextAuth from ''next-auth'' and export const { handlers, signIn, signOut, auth } = NextAuth({ providers: [] }). Then create the App Router route handler at app/api/auth/[...nextauth]/route.ts that re-exports GET and POST from handlers. Fill the providers array with built-in providers imported from next-auth/providers/*. Other frameworks have their own init helpers but share this auth.ts convention. This is a short original summary for agents, not a substitute for the official documentation.', 'https://authjs.dev/getting-started/installation', 'ISC', '6742c13657cb1d100c035d2893f095aa922013a0cd80ee5e61b8d2dbba534d02', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('authjs-proxy-next16', 'authjs', '5.0.0-beta', 'Next.js 16 renamed middleware.ts to proxy.ts for the auth wrapper', 'Auth.js can wrap a Next.js proxy (formerly middleware) so the session is kept alive as requests pass through. Official installation notes that as of Next.js 16, middleware.ts has been renamed to proxy.ts. On Next.js 16, use the proxy file with the auth wrapper; on older Next.js, keep middleware.ts and export { auth as middleware }. This optional step is for session refresh and protecting routes, not a substitute for the /api/auth route handler. This is a short original summary for agents, not a substitute for the official documentation.', 'https://authjs.dev/getting-started/installation', 'ISC', '4aa340d60a1e1f67167fe1e561f78dcbf29549891f617f6a41da9bc9e36b3808', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('authjs-providers', 'authjs', '5.0.0-beta', 'Auth.js supports OAuth, magic links, credentials, and WebAuthn', 'Official getting-started lists four authentication methods: OAuth (Google, GitHub, LinkedIn, and many others), magic links (email providers such as Resend, Nodemailer, or SendGrid), credentials (username/password or an external API), and WebAuthn/passkeys. Optional database adapters persist users and accounts if you need them. Configure each method as a provider in the NextAuth({ providers }) array (or the equivalent for your framework) rather than rolling a custom token endpoint. This is a short original summary for agents, not a substitute for the official documentation.', 'https://authjs.dev/getting-started', 'ISC', 'b6561cc75f0a35884c1471ec379d4cc8d04ec9d8e75fdf7d8fad1c2851d7660d', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('bun-install', 'bun', '1.4', 'Install the Bun executable with the official script or a package manager', 'Bun ships as a single executable. On macOS and Linux: curl -fsSL https://bun.com/install | bash (Linux needs unzip; kernel 5.6+ is recommended). On Windows 10 1809 or later: powershell -c "irm bun.sh/install.ps1|iex". You can also npm install -g bun, brew install oven-sh/bun/bun, scoop install bun, or docker pull oven/bun. Verify with bun --version and bun --revision. If the shell says command not found, add ~/.bun/bin to PATH (BUN_INSTALL=$HOME/.bun). This is a short original summary for agents, not a substitute for the official documentation.', 'https://bun.com/docs/installation', 'MIT', '3c380e186ce7c3b7f447a70f570113287b2876d6b65c3eb8166908aaf736084c', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('bun-run-scripts', 'bun', '1.4', 'bun run executes TypeScript and package.json scripts directly', 'bun run index.ts runs a TypeScript or JavaScript file without a separate transpile step. Scripts in package.json work as bun run start (or bun run <script>). Official quickstart notes that bun run has much less overhead than npm run. bun install installs packages; bun add adds one. A typical new project uses { "module": "index.ts", "type": "module" } and may include @types/bun. bun init can scaffold that layout. This is a short original summary for agents, not a substitute for the official documentation.', 'https://bun.com/docs/quickstart', 'MIT', '85f2f3c91a1442aec074356b0be807f713b1783afec690fb750632e34e4d5932', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('bun-serve', 'bun', '1.4', 'Bun.serve starts an HTTP server with a routes object', 'const server = Bun.serve({ port: 3000, routes: { ''/'': indexHtml, ''/figlet'': () => new Response(body) } }) is the documented pattern. Route values can be a Response, an HTML import, or a function that returns a Response. After start, server.url is the listening origin (for example http://localhost:3000/). This is the built-in server; you do not need Express to serve HTTP from Bun. This is a short original summary for agents, not a substitute for the official documentation.', 'https://bun.com/docs/runtime/http/server', 'MIT', '5f899e1be1b6ef0d056a2c72ac9c905c39adc5e99ad2be1c5e5e4661d8c350cf', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('bun-test', 'bun', '1.4', 'bun:test is a Jest-compatible runner invoked with bun test', 'import { expect, test, describe } from ''bun:test'' and write test(''2 + 2'', () => { expect(2 + 2).toBe(4) }). Group suites with describe, and use async test callbacks or a done callback (you must call done() or the test hangs). A third argument to test() is a timeout in milliseconds (default 5000). Run the runner with bun test. Long term, Bun aims for complete Jest compatibility; module mocks, hooks, and snapshots are documented separately. This is a short original summary for agents, not a substitute for the official documentation.', 'https://bun.com/docs/test/writing-tests', 'MIT', '1ea1ba358ff61d1d2e528eac74948057c84bd8a9462b3ef588ed088b2bbe21b3', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sqlalchemy-engine', 'sqlalchemy', '2.1', 'create_engine() is the starting point for every application', 'from sqlalchemy import create_engine; engine = create_engine(''sqlite+pysqlite:///:memory:'', echo=True) builds an Engine. The URL names the dialect (sqlite), the DBAPI (pysqlite, optional when there is a default), and the location (/:memory: here). echo=True logs SQL, which is useful while learning. The Engine is usually a single global per database and includes a connection pool. create_engine() does not connect immediately; the first real operation opens a connection (lazy initialization). This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.sqlalchemy.org/en/21/tutorial/engine.html', 'MIT', 'eaf58f9c6e067e43e332e00f78e422c0a789c848386aedd1af1ee43fddad7b6a', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sqlalchemy-core-and-orm', 'sqlalchemy', '2.1', 'SQLAlchemy 2.1 is one Unified Tutorial covering Core and ORM', 'SQLAlchemy has two APIs: Core (engine, Connection, Result, SQL expression language, metadata) and the ORM (mapped classes, Session, relationship()), which builds on Core. In 2.0-style (including 2.1) the ORM uses the same select() construct as Core, and transactional patterns line up between Connection and Session. Official 2.1 docs ask you to confirm sqlalchemy.__version__ starts with 2.1. New code should follow the Unified Tutorial, not the 1.x Query API. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.sqlalchemy.org/en/21/tutorial/index.html', 'MIT', 'b54e89fbd0851e1831d6e7b5ac5e57949cb64cefa66b00e4ccf8ae39733f070a', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sqlalchemy-declarative', 'sqlalchemy', '2.1', 'DeclarativeBase and mapped_column define ORM mapped classes', 'In the 2.x ORM, subclass DeclarativeBase for your Base, then declare classes with __tablename__ and typed attributes: id: Mapped[int] = mapped_column(primary_key=True). Import DeclarativeBase, Mapped, and mapped_column from sqlalchemy.orm. Call Base.metadata.create_all(engine) to emit CREATE TABLE in simple scripts, or use Alembic for real migrations. This declarative form is the documented quickstart style in 2.1. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.sqlalchemy.org/en/21/orm/quickstart.html', 'MIT', '89557fe5b456c12dad58e48d2d12ca1b5d970f0e1f69d954dc6c515107483987', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('sqlalchemy-session-select', 'sqlalchemy', '2.1', 'Session and select() are the 2.x way to load and persist objects', 'Open a session with with Session(engine) as session: (or a sessionmaker factory). Add new objects with session.add(), then session.commit() to persist. Load rows with select(User) and session.scalars(...) or session.execute(...). Filter with select(User).where(User.name == ''ed''). Do not use the legacy Query API in new 2.1 code. Close or context-manage the Session so connections return to the pool. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.sqlalchemy.org/en/21/tutorial/orm_data_manipulation.html', 'MIT', '79db5dc003616b0bec213520068d981ffb24c98287e2d30cdc231d6316c58404', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('llamaindex-function-agent', 'llamaindex', '0.14', 'FunctionAgent runs an LLM with Python callables as tools', 'The official starter builds an agent with FunctionAgent from llama_index.core.agent.workflow, passing tools=[multiply], an llm such as OpenAI(model=''gpt-4o-mini''), and a system_prompt. Call await agent.run(''What is 1234 * 4567?'') inside asyncio.run(main()). Tool functions and their docstrings become the tool schema. Official docs recommend async code because many model providers support async calls. Default LLM wiring uses OpenAI; set OPENAI_API_KEY in the environment. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.llamaindex.ai/en/stable/getting_started/starter_example/', 'MIT', 'e14bf124c76dc1a2e444858ebbefdcc4fed0da48fa3487142601bec3ca980603', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('llamaindex-agent-context', 'llamaindex', '0.14', 'Pass a Context to FunctionAgent.run to keep chat history', 'AgentWorkflow (including FunctionAgent) can remember prior turns when you pass a Context. Create ctx = Context(agent) from llama_index.core.workflow, then await agent.run(''My name is Logan'', ctx=ctx) and later await agent.run(''What is my name?'', ctx=ctx). Without a shared Context, each run is independent. Keep one Context per conversation, not a global shared across users. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.llamaindex.ai/en/stable/getting_started/starter_example/', 'MIT', '36ba2d2cf20df17488b7d7c7f768ba1d4d8f1b100ab7b53707ad435f290d20dd', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('llamaindex-vector-index', 'llamaindex', '0.14', 'VectorStoreIndex and SimpleDirectoryReader add RAG to an agent', 'documents = SimpleDirectoryReader(''data'').load_data(); index = VectorStoreIndex.from_documents(documents); query_engine = index.as_query_engine() builds an in-memory index over files in data/. Wrap query_engine.aquery(query) in an async tool and pass that tool to FunctionAgent so the agent can search documents. With no Settings.embed_model configured, VectorStoreIndex falls back to OpenAIEmbedding (historically text-embedding-ada-002). Official docs recommend passing OpenAIEmbedding(model=''text-embedding-3-small'') explicitly in new projects, or a local HuggingFaceEmbedding. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.llamaindex.ai/en/stable/getting_started/starter_example/', 'MIT', '885c01a6e6a2e42aeaf34dc30dd75cd6249c883c21a7c17572117e73d72d96ca', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('llamaindex-persist-index', 'llamaindex', '0.14', 'storage_context.persist saves an index so you can reload it', 'index.storage_context.persist(''storage'') writes the index to disk. Later: from llama_index.core import StorageContext, load_index_from_storage; storage_context = StorageContext.from_defaults(persist_dir=''storage''); index = load_index_from_storage(storage_context). If you used a vector store integration other than the default, you can often rebuild with VectorStoreIndex.from_vector_store(vector_store) instead of the local persist folder. Persisting avoids re-embedding documents on every process start. This is a short original summary for agents, not a substitute for the official documentation.', 'https://docs.llamaindex.ai/en/stable/getting_started/starter_example/', 'MIT', 'a19c32f4441734c823e9c4b6a227623ff63ecda7251943b337ee07b7597d654e', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-router-modes', 'react-router', '8.5', 'React Router 8 has Declarative, Data, and Framework modes', 'React Router is a multi-strategy router. Declarative mode is the basic <BrowserRouter> style with Route, Link, useNavigate, and useLocation. Data mode moves route config outside of render and adds loader, action, and useFetcher via createBrowserRouter and RouterProvider. Framework mode wraps Data mode with a Vite plugin for type-safe route modules, href, code splitting, and SPA/SSR/static strategies. Features are additive: moving Declarative → Data → Framework adds capabilities and reduces some architectural control. Official docs say upgrading from v7 is generally non-breaking if you are caught up on future flags. This is a short original summary for agents, not a substitute for the official documentation.', 'https://reactrouter.com/start/modes', 'MIT', '76dddb81881b29d269d6f6959cf938e149fa70218a28f231f037344453abaf6f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-router-declarative', 'react-router', '8.5', 'Declarative mode wraps the app in BrowserRouter', 'import { BrowserRouter } from ''react-router'' and render <BrowserRouter><App /></BrowserRouter> (from react-dom). This mode gives URL matching, navigation, and active states with APIs such as Link, useNavigate, and useLocation. Official advice is to use it when you want the simplest router, you are coming from earlier React Router versions and are happy with BrowserRouter, or you already have your own data layer. Import from ''react-router'', not the old ''react-router-dom'' package name, in current v8 docs. This is a short original summary for agents, not a substitute for the official documentation.', 'https://reactrouter.com/start/modes', 'MIT', '8048c11d34d9291579ed3ae3cc50666be30780a55bcfa67401a03255d7c4a83f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-router-data-mode', 'react-router', '8.5', 'createBrowserRouter and RouterProvider enable loaders and actions', 'import { createBrowserRouter, RouterProvider } from ''react-router''. let router = createBrowserRouter([{ path: ''/'', Component: Root, loader: loadRootData }]); then render <RouterProvider router={router} />. Because the route tree is defined outside of React render, loaders, actions, pending states, and useFetcher are available. Official docs recommend Data mode when you want those features but still want to control bundling and the server yourself, including apps that started a data router in v6.4. This is a short original summary for agents, not a substitute for the official documentation.', 'https://reactrouter.com/start/modes', 'MIT', '3ddaabb4456ac02e0c898b04ad5e421bd62049cc36cf002ecdf40661553f043f', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('react-router-framework-mode', 'react-router', '8.5', 'Framework mode uses a route module API and create-react-router', 'Framework mode is scaffolded with the official installer (npx create-react-router@latest) and a routes file that uses index() and route() from @react-router/dev/routes, for example route(''products/:pid'', ''./product.tsx''). Route modules can export loader and a default component; types come from ''./+types/product.tsx'' (Route.LoaderArgs, Route.ComponentProps, loaderData, typed params). You also get type-safe href, code splitting, and SPA, SSR, or static rendering. Official docs point newcomers who just want to build with React (or who are comparing Next.js, SvelteKit, and similar) to Framework mode. This is a short original summary for agents, not a substitute for the official documentation.', 'https://reactrouter.com/start/framework/installation', 'MIT', 'd5a55a2bcf19147cb0a35b8e396847986b0b593d1e5eed72b96ef2c17f1a3f38', 'house', 1, 'verified', '2026-11-21T00:00:00.000Z', '2026-11-21');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vitest-getting-started', 'vitest', '5.1', 'Install Vitest 5 and run tests once with vitest run', 'Install as a dev dependency: npm install -D vitest. Yarn users must also add vite (yarn add -D vitest vite) because vite is now a required peer dependency of vitest. Vitest 5 requires Vite >= 6.4.0 and Node.js >= 22.12.0. Test files must contain .test. or .spec. in the name: import { expect, test } from ''vitest''; test(''adds 1 + 2 to equal 3'', () => { expect(sum(1, 2)).toBe(3) }). Add "test": "vitest" to package.json scripts; plain vitest watches for changes, while vitest run runs once and exits. Vitest reads vite.config.* by default, or a dedicated vitest.config.* exporting defineConfig({ test: { ... } }) from ''vitest/config''. Generated reports and artifacts go in a .vitest/ directory, which the docs recommend adding to .gitignore. With Bun as the package manager, run bun run test, not bun test (that starts Bun''s own test runner). This is a short original summary for agents, not a substitute for the official documentation.', 'https://vitest.dev/guide/', 'MIT', '8bdb6fb93192e8257a0e1552afb4cd0163ec619b282d68eefccab56268f09815', 'house', 1, 'verified', '2026-11-22T00:00:00.000Z', '2026-11-22');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vitest-5-behavior-changes', 'vitest', '5.1', 'Vitest 5 behavior changes: clearMocks on by default, unawaited assertions fail, vi.mock must be top level', 'Vitest 5.0 changes defaults that can break v4-era tests. clearMocks now defaults to true: vi.clearAllMocks() runs before every test, so mock call history recorded in setup files, at module top level, or in beforeAll is cleared before the test asserts (implementations are kept); set test: { clearMocks: false } to restore v4 behavior. Async assertions such as expect(p).resolves, .rejects, and toMatchFileSnapshot now fail the test when not awaited (v4 auto-awaited with a warning), so write await expect(p).resolves.toBe(1). vi.mock, vi.unmock, and vi.hoisted inside a function, block, or describe/test callback now throw; move them to module top level (vi.doMock and vi.doUnmock may still be called anywhere). expect.poll rejects if the callback or assertion does not settle within timeout, and the callback receives an AbortSignal. testNamePattern (-t) matches the full name joined with '' > '', e.g. vitest -t ''math > adds''. Inline test.projects now inherit the root config (extends defaults to true), including plugins and resolve.alias; set extends: false to opt out. This is a short original summary for agents, not a substitute for the official documentation.', 'https://vitest.dev/guide/migration.html', 'MIT', '0986e8a9f7296e56498ec7f507ca1395f036d29a7599b6a33b97ccc301946b82', 'house', 1, 'verified', '2026-11-22T00:00:00.000Z', '2026-11-22');
INSERT OR IGNORE INTO snippets (id, library, library_version, title, body, source_url, license, content_hash, submitter_wallet, house_owned, status, created_at, retrieved_at) VALUES ('vitest-5-removed-apis', 'vitest', '5.1', 'Vitest 5 removed APIs: bench is a test fixture, test.sequential is gone, old entry points removed', 'bench is no longer a top-level import from ''vitest''; destructure it from the test context: test(''sort'', async ({ bench }) => { await bench(''sort'', () => { [3, 1, 2].sort() }).run() }). bench.skip/only/todo, benchmark.reporters, benchmark.outputFile, benchmark.compare (--compare), and benchmark.outputJson (--outputJson) are removed; use test.skip/only/todo on the surrounding test, top-level test.reporters, and --reporter=json --outputFile=<file>. test.sequential, describe.sequential, and the sequential option are removed: use test(''x'', { concurrent: false }, fn) or describe(''s'', { concurrent: false }, fn). Entry points deprecated in 4.1 are gone: import from vitest/node instead of vitest/coverage or vitest/reporters, from vitest/runtime instead of vitest/environments or vitest/snapshot, and use TestRunner from ''vitest'' instead of vitest/runners or vitest/suite (e.g. TestRunner.getCurrentTest()). vitest no longer depends on @vitest/expect; use expect, expect.extend, and chai from ''vitest''. Custom matcher types augment Matchers<R, T>; the global jest.Matchers interface is no longer read. This is a short original summary for agents, not a substitute for the official documentation.', 'https://vitest.dev/guide/migration.html', 'MIT', 'bb345a7a7413e00a179d966bdf91db565a77b91081352340daf3a972cbccea7e', 'house', 1, 'verified', '2026-11-22T00:00:00.000Z', '2026-11-22');
